INSERT INTO canonical_workplace_safety_questions VALUES
(md5('safety:높은 장소에서 작업 시 안전모 외에 착용해야 하는 보호구는 무엇인가요?')::uuid, '높은 장소에서 작업 시 안전모 외에 착용해야 하는 보호구는 무엇인가요?', 'Khi làm việc ở nơi cao, ngoài mũ bảo hộ còn phải đeo đồ bảo hộ nào?', '["높은 장소에서 작업하는 경우에는 안전대를 착용하고, 안전대 부착설비에 고리를 체결해야 합니다.", "높은 장소에서 작업 시 안전대를 착용하고 고리를 체결해야 합니다."]'::jsonb, '["Khi làm việc ở nơi cao, phải đeo dây an toàn và móc dây vào thiết bị neo dây an toàn.", "Khi làm việc ở nơi cao, phải đeo dây an toàn và móc dây vào."]'::jsonb, 'before_work', 1, '보호구 착용', 'Sử dụng trang thiết bị bảo hộ lao động'),
(md5('safety:머리를 보호하기 위해 착용하는 보호구는 무엇인가요?')::uuid, '머리를 보호하기 위해 착용하는 보호구는 무엇인가요?', 'Đồ bảo hộ dùng để bảo vệ đầu là gì?', '["머리를 보호하기 위해서는 안전모를 착용해야 합니다. 안전모 착용 시에는 턱끈을 조여야 합니다.", "안전모를 착용해야 합니다."]'::jsonb, '["Để bảo vệ đầu, phải đội mũ bảo hộ. Khi đội mũ bảo hộ, phải thắt chặt quai cằm.", "Phải đội mũ bảo hộ."]'::jsonb, 'before_work', 1, '보호구 착용', 'Sử dụng trang thiết bị bảo hộ lao động'),
(md5('safety:보호구가 무엇인가요?')::uuid, '보호구가 무엇인가요?', 'Đồ bảo hộ là gì?', '["보호구는 작업 중 발생할 수 있는 위험으로부터 작업자의 신체를 보호하기 위해 착용하거나 사용하는 장비나 용품입니다.", "보호구는 작업 중 작업자의 생명과 건강을 지키기 위한 필수 장비입니다."]'::jsonb, '["Đồ bảo hộ là các thiết bị hoặc dụng cụ được mang hoặc sử dụng nhằm bảo vệ cơ thể của người lao động khỏi những nguy hiểm có thể xảy ra trong quá trình làm việc.", "Đồ bảo hộ là thiết bị thiết yếu để bảo vệ tính mạng và sức khỏe của người lao động trong quá trình làm việc."]'::jsonb, 'before_work', 1, '보호구 착용', 'Sử dụng trang thiết bị bảo hộ lao động'),
(md5('safety:보호구를 왜 착용하여야 할까요?')::uuid, '보호구를 왜 착용하여야 할까요?', 'Tại sao phải sử dụng đồ bảo hộ?', '["보호구를 착용하여야 하는 이유는 작업자의 생명과 건강을 지키기 위한 가장 기본적이고 필수적인 조치이기 때문입니다.", "보호구는 작업자의 생명과 건강을 지키기 위해 착용하기 때문입니다."]'::jsonb, '["Lý do phải sử dụng đồ bảo hộ là vì đây là biện pháp cơ bản và thiết yếu nhất để bảo vệ tính mạng và sức khỏe của người lao động.", "Vì đồ bảo hộ được sử dụng để bảo vệ tính mạng và sức khỏe của người lao động."]'::jsonb, 'before_work', 1, '보호구 착용', 'Sử dụng trang thiết bị bảo hộ lao động'),
(md5('safety:보호구에는 어떤 종류가 있나요?')::uuid, '보호구에는 어떤 종류가 있나요?', 'Đồ bảo hộ có những loại nào?', '["안전모, 안전화, 안전대, 보안면, 귀마개, 방진마스크,방독마스크, 방열복, 방한복 등이 있습니다.", "안전모는 작업자가 물체와 부딪치거나 바닥으로 떨어졌을 때 머리를 보호하는 모자입니다.", "안전모는 충격으로부터 머리를 보호하는 모자입니다.", "안전화는 떨어지는 공구 또는 뾰족한 물건으로부터 발을 보호하기 위한 신발입니다.", "안전화는 작업 중 발을 보호하는 신발입니다.", "안전대는 작업자가 높은 곳에서 바닥으로 떨어지는 것을 막는 장비입니다.", "보안면은 불꽃이나 날아오는 물체로부터 얼굴과 눈을 보호하기 위한 장비입니다.", "보안면은 작업 중 얼굴과 눈을 보호하는 장비입니다.", "귀마개는 시끄럽고 큰 소리가 나는 장소에서 귀를 보호하기 위한 용품입니다.", "귀마개는 큰 소리로부터 귀를 보호하는 용품입니다.", "방진마스크는 공기 중에 있는 먼지로부터 입과 코를 보호하기 위한 용품입니다.", "방진마스크는 먼지로부터 입과 코를 보호하는 용품입니다.", "방독마스크는 공기 중에 있는 화학물질 등으로부터 입과 코를 보호하기 위한 용품입니다.", "방독마스크는 화학물질로부터 입과 코를 보호하는 용품입니다.", "방열복은 매우 뜨거운 장소에서 열과 불로부터 몸을 보호하기 위한 작업복입니다.", "방열복은 열과 불로부터 몸을 보호하는 작업복입니다.", "방한복은 매우 추운 장소에서 몸 온도를 유지하기 위한 보온용 작업복입니다.", "한복은 몸을 따뜻하게 하는 작업복입니다."]'::jsonb, '["Có mũ bảo hộ, giày bảo hộ, dây an toàn, mặt nạ bảo hộ, nút bịt tai, khẩu trang chống bụi, mặt nạ phòng độc, quần áo chống nóng, quần áo chống rét, v.v.", "Mũ bảo hộ là loại mũ dùng để bảo vệ đầu của người lao động khi va chạm với vật thể hoặc bị ngã xuống sàn.", "Mũ bảo hộ là loại mũ dùng để bảo vệ đầu khỏi tác động của lực va đập.", "Giày bảo hộ là loại giày dùng để bảo vệ chân khỏi các dụng cụ rơi xuống hoặc những vật sắc nhọn.", "Giày bảo hộ là loại giày dùng để bảo vệ chân trong quá trình làm việc.", "Dây an toàn là thiết bị ngăn người lao động rơi từ trên cao xuống mặt đất.", "Mặt nạ bảo hộ là thiết bị dùng để bảo vệ mặt và mắt khỏi tia lửa hoặc các vật thể bay đến.", "Mặt nạ bảo hộ là thiết bị bảo vệ mặt và mắt trong quá trình làm việc.", "Nút bịt tai là dụng cụ dùng để bảo vệ tai tại những nơi có tiếng ồn lớn và ồn ào.", "Nút bịt tai là dụng cụ bảo vệ tai khỏi tiếng ồn lớn.", "Khẩu trang chống bụi là dụng cụ dùng để bảo vệ miệng và mũi khỏi bụi trong không khí.", "Khẩu trang chống bụi là dụng cụ bảo vệ miệng và mũi khỏi bụi.", "Mặt nạ phòng độc là dụng cụ dùng để bảo vệ miệng và mũi khỏi các chất hóa học có trong không khí.", "Mặt nạ phòng độc là dụng cụ bảo vệ miệng và mũi khỏi các chất hóa học.", "Quần áo chống nóng là quần áo bảo hộ lao động dùng để bảo vệ cơ thể khỏi nhiệt và lửa ở những nơi có nhiệt độ rất cao.", "Quần áo chống nóng là quần áo bảo hộ lao động bảo vệ cơ thể khỏi nhiệt và lửa.", "Quần áo chống rét là quần áo bảo hộ lao động dùng để giữ ấm cơ thể ở những nơi rất lạnh.", "Quần áo giữ ấm là quần áo bảo hộ lao động giúp cơ thể ấm áp."]'::jsonb, 'before_work', 1, '보호구 착용', 'Sử dụng trang thiết bị bảo hộ lao động'),
(md5('safety:대피로는 무엇인가요?')::uuid, '대피로는 무엇인가요?', 'Lối thoát hiểm là gì?', '["대피로는 화재 등 위급 상황이 발생했을 때 작업자가 신속하고 안전하게 빠져나갈 수 있도록 사전에 확보된 이동 경로입니다.", "대피로는 위급 상황에서 안전하게 대피하는 이동 경로입니다."]'::jsonb, '["Lối thoát hiểm là tuyến đường di chuyển được bố trí và đảm bảo sẵn từ trước để người lao động có thể nhanh chóng và an toàn thoát ra ngoài khi xảy ra tình huống khẩn cấp như hỏa hoạn.", "Lối thoát hiểm là tuyến đường di chuyển để sơ tán an toàn trong tình huống khẩn cấp."]'::jsonb, 'before_work', 2, '비상구 등 대피로 확인', 'Kiểm tra cửa thoát hiểm và lối thoát hiểm'),
(md5('safety:비상구 등 대피로를 왜 확인해야 할까요?')::uuid, '비상구 등 대피로를 왜 확인해야 할까요?', 'Tại sao cần kiểm tra cửa thoát hiểm và lối thoát hiểm?', '["비상구 등 대피로를 확인해야 하는 이유는 사고가 발생하였을 때 생명을 지키기 위한 가장 기본적인 재난 대응 수칙으로 신속한 이동이 가능하기 때문입니다.", "비상구와 대피로는 사고가 났을 때 신속하게 대피하기 위해 확인해야 합니다.", "사고가 났을 때 빨리 대피하기 위해서입니다."]'::jsonb, '["Lý do cần kiểm tra cửa thoát hiểm và lối thoát hiểm là vì đây là quy tắc ứng phó với thảm họa cơ bản nhất để bảo vệ tính mạng, giúp có thể di chuyển nhanh chóng khi xảy ra sự cố.", "Phải kiểm tra cửa thoát hiểm và lối thoát hiểm để nhanh chóng sơ tán khi xảy ra sự cố.", "Để nhanh chóng sơ tán khi xảy ra sự cố."]'::jsonb, 'before_work', 2, '비상구 등 대피로 확인', 'Kiểm tra cửa thoát hiểm và lối thoát hiểm'),
(md5('safety:비상구가 무엇인가요?')::uuid, '비상구가 무엇인가요?', 'Cửa thoát hiểm là gì?', '["비상구란: 화재, 지진 등 갑작스러운 사고가 일어났을 때 신속하게 대피할 수 있도록 마련된 출입구입니다.", "비상구는 화재나 지진 등 사고가 났을 때 대피하는 출입구입니다.", "비상구는 사고가 났을 때 대피하는 출입구입니다."]'::jsonb, '["Cửa thoát hiểm là: lối ra vào được bố trí để có thể nhanh chóng sơ tán khi xảy ra các sự cố bất ngờ như hỏa hoạn, động đất, v.v.", "Cửa thoát hiểm là lối ra vào để sơ tán khi xảy ra sự cố như hỏa hoạn hoặc động đất,v.v..", "Cửa thoát hiểm là lối ra vào để sơ tán khi xảy ra sự cố."]'::jsonb, 'before_work', 2, '비상구 등 대피로 확인', 'Kiểm tra cửa thoát hiểm và lối thoát hiểm'),
(md5('safety:소화기란 무엇이며 소화기의 색상은 어떻게 되나요?')::uuid, '소화기란 무엇이며 소화기의 색상은 어떻게 되나요?', 'Bình chữa cháy là gì và bình chữa cháy có màu như thế nào?', '["소화기란 불을 끄기 위한 도구로 보통은 붉은색 입니다. 평소에 소화기의 위치를 확인해 두는 것이 중요합니다.", "소화기란 불을 끄기 위한 도구로 보통은 붉은색입니다."]'::jsonb, '["Bình chữa cháy là dụng cụ dùng để dập lửa, thường có màu đỏ. Việc xác định trước vị trí của bình chữa cháy là rất quan trọng.", "Bình chữa cháy là dụng cụ dùng để dập lửa, thường có màu đỏ."]'::jsonb, 'before_work', 2, '비상구 등 대피로 확인', 'Kiểm tra cửa thoát hiểm và lối thoát hiểm'),
(md5('safety:안전보건표지가 무엇인가요?')::uuid, '안전보건표지가 무엇인가요?', 'Biển báo an toàn nghề nghiệp là gì?', '["안전보건표지란 작업장 내 위험요인을 알리고, 안전한 행동을 유도하기 위해 사용하는 시각적 표지입니다.", "안전보건표지는 위험을 알리고 안전한 행동을 유도하는 표지입니다."]'::jsonb, '["Biển báo an toàn nghề nghiệp là các biển báo trực quan được sử dụng để thông báo về các yếu tố nguy hiểm tại nơi làm việc và hướng dẫn người lao động thực hiện hành vi an toàn.", "Biển báo an toàn là biển báo dùng để cảnh báo nguy hiểm và hướng dẫn thực hiện hành vi an toàn."]'::jsonb, 'before_work', 3, '안전보건표지 확인', 'Kiểm tra biển báo an toàn trong lao động'),
(md5('safety:안전보건표지에는 어떤 종류가 있을까요?')::uuid, '안전보건표지에는 어떤 종류가 있을까요?', 'Biển báo an toàn có những loại nào?', '["안전보건표지의 종류에는 위험행동을 막기 위한 금지표지, 위험에 대한 주의 위험 경고 표시, 안전행동 유도를 위한 지시표시, 대피경로 등을 알려주기 위한 안내표지가 있습니다.", "안전보건표지는 금지표지, 경고표지, 지시표지, 안내표지가 있습니다."]'::jsonb, '["Các loại biển báo an toàn gồm: biển báo cấm để ngăn chặn hành vi nguy hiểm, biển báo cảnh báo để cảnh báo về các mối nguy hiểm, biển báo chỉ dẫn để hướng dẫn thực hiện hành vi an toàn và biển báo hướng dẫn để chỉ dẫn đường sơ tán, v.v.", "Biển báo an toàn gồm: biển báo cấm, biển báo cảnh báo, biển báo chỉ dẫn và biển báo hướng dẫn."]'::jsonb, 'before_work', 3, '안전보건표지 확인', 'Kiểm tra biển báo an toàn trong lao động'),
(md5('safety:위험장소 출입금지 등 금지표지는 무슨 색인가요?')::uuid, '위험장소 출입금지 등 금지표지는 무슨 색인가요?', 'Biển báo cấm như cấm ra vào khu vực nguy hiểm có màu gì?', '["출입 금지 등 위험 행동을 막기 위한 금지표지는 붉은색 원 모양에 붉은색으로 사선이 그려져 있습니다.", "금지표지는 위험 행동을 막는 표지로, 붉은색 원에 붉은 사선이 있습니다."]'::jsonb, '["Biển báo cấm dùng để ngăn chặn các hành vi nguy hiểm như cấm ra vào, có hình tròn màu đỏ và có một đường chéo màu đỏ.", "Biển báo cấm là biển báo ngăn chặn hành vi nguy hiểm, có hình tròn màu đỏ với một đường chéo màu đỏ."]'::jsonb, 'before_work', 3, '안전보건표지 확인', 'Kiểm tra biển báo an toàn trong lao động'),
(md5('safety:방호장치 정상 작동 여부를 왜 확인하여야 하나요?')::uuid, '방호장치 정상 작동 여부를 왜 확인하여야 하나요?', 'Tại sao phải kiểm tra thiết bị bảo vệ có hoạt động bình thường hay không?', '["방호장치 정상 작동 여부를 확인하는 이유는 사람이 실수를 하더라도 방호장치가 정상적으로 작동해야만 실질적인 보호 효과가 있기 때문입니다.", "방호장치가 정상 작동해야 사람이 실수를 하더라도 작업자를 안전하게 보호할 수 있기 때문입니다."]'::jsonb, '["Lý do phải kiểm tra thiết bị bảo vệ có hoạt động bình thường hay không là vì ngay cả khi con người mắc sai sót, thiết bị bảo vệ phải hoạt động bình thường thì mới có thể mang lại hiệu quả bảo vệ thực sự.", "Vì thiết bị bảo vệ phải hoạt động bình thường thì mới có thể bảo vệ người lao động an toàn ngay cả khi họ mắc sai sót."]'::jsonb, 'before_work', 4, '방호장치 정상 작동 여부 확인', 'Kiểm tra thiết bị an toàn có hoạt động hay không'),
(md5('safety:방호장치가 무엇인가요?')::uuid, '방호장치가 무엇인가요?', 'Thiết bị bảo vệ là gì?', '["방호장치는 기계 등에서 발생하는 위험 요인으로부터 작업자의 신체를 보호하거나 위험을 차단하는 설비입니다.", "방호장치는 위험 요인으로부터 신체를 보호하거나 위험을 차단하는 설비입니다."]'::jsonb, '["Thiết bị bảo vệ là thiết bị dùng để bảo vệ cơ thể người lao động hoặc ngăn chặn các yếu tố nguy hiểm phát sinh từ máy móc và các thiết bị khác.", "Thiết bị bảo vệ là thiết bị dùng để bảo vệ cơ thể khỏi các yếu tố nguy hiểm hoặc ngăn chặn nguy hiểm."]'::jsonb, 'before_work', 4, '방호장치 정상 작동 여부 확인', 'Kiểm tra thiết bị an toàn có hoạt động hay không'),
(md5('safety:작업 전 안전점검이 무엇인가요?')::uuid, '작업 전 안전점검이 무엇인가요?', 'Kiểm tra an toàn trước khi làm việc là gì?', '["작업 시작 전 기계의 정상 작동 여부를 점검합니다. 기계에서 이상한 소리가 나거나 흔들리거나 하면 사용하지 말고 반장님 등 관리자에게 보고해야 합니다.", "작업 전에 기계를 점검하고, 이상이 있으면 사용하지 말고 관리자에게 보고해야 합니다."]'::jsonb, '["Trước khi bắt đầu công việc, phải kiểm tra máy móc có hoạt động bình thường hay không. Nếu máy phát ra tiếng động bất thường hoặc bị rung lắc thì không được sử dụng mà phải báo cáo cho quản lý như tổ trưởng.", "Trước khi làm việc, phải kiểm tra máy móc; nếu có bất thường thì không được sử dụng mà phải báo cáo cho quản lý."]'::jsonb, 'before_work', 4, '방호장치 정상 작동 여부 확인', 'Kiểm tra thiết bị an toàn có hoạt động hay không'),
(md5('safety:정상 작동이 무슨 뜻인가요?')::uuid, '정상 작동이 무슨 뜻인가요?', '“Hoạt động bình thường” có nghĩa là gì?', '["정상 작동이란 장치, 설비 등이 정해진 목적과 기준에 맞게 안전하고 정확하게 작동하는 상태입니다.", "정상 작동은 장치와 설비가 기준에 맞게 안전하게 작동하는 상태입니다."]'::jsonb, '["Hoạt động bình thường là trạng thái thiết bị, máy móc... hoạt động an toàn và chính xác theo đúng mục đích và tiêu chuẩn đã quy định.", "Hoạt động bình thường là trạng thái thiết bị và máy móc hoạt động an toàn theo đúng tiêu chuẩn."]'::jsonb, 'before_work', 4, '방호장치 정상 작동 여부 확인', 'Kiểm tra thiết bị an toàn có hoạt động hay không'),
(md5('safety:MSDS(물질안전보건자료)가 무엇인가요?')::uuid, 'MSDS(물질안전보건자료)가 무엇인가요?', 'MSDS (물질안전보건자료) là gì?', '["MSDS(물질안전보건자료)란 화학물질에 대한 정보(이름, 성분, 유해성, 위험성, 보관방법, 다룰 때 주의할 점, 필요한 보호구, 응급조치 등)가 담긴 설명서입니다.", "MSDS는 화학물질의 정보, 주의사항, 보호구와 응급조치가 있는 설명서입니다."]'::jsonb, '["MSDS (물질안전보건자료) là phiếu an toàn hóa chất, chứa các thông tin về hóa chất như: tên, thành phần, tính độc hại, mức độ nguy hiểm, cách bảo quản, những điều cần lưu ý khi sử dụng, đồ bảo hộ cần thiết, biện pháp sơ cứu, v.v.", "MSDS là tài liệu chứa các thông tin về hóa chất, các lưu ý, đồ bảo hộ và biện pháp sơ cứu, vv.."]'::jsonb, 'before_work', 5, '화학물질 MSDS(물질안전보건자료) 확인', 'Kiểm tra MSDS (Bảng dữ liệu an toàn hóa chất)'),
(md5('safety:화학물질 MSDS(물질안전보건자료)를 왜 확인해야 할까요?')::uuid, '화학물질 MSDS(물질안전보건자료)를 왜 확인해야 할까요?', 'Tại sao cần kiểm tra MSDS (Phiếu an toàn hóa chất) của hóa chất?', '["화학물질 MSDS(물질안전보건자료)를 확인해야 하는 이유는 화학물질을 안전하게 취급하고 사고를 예방하기 위해 반드시 확인해야 하는 가장 기본적인 안전정보이기 때문입니다.", "화학물질을 안전하게 취급하고 사고를 예방하기 위해 MSDS를 확인해야 합니다."]'::jsonb, '["Lý do cần kiểm tra MSDS của hóa chất là vì đây là thông tin an toàn cơ bản và bắt buộc phải kiểm tra để sử dụng, xử lý hóa chất an toàn và phòng ngừa tai nạn.", "Cần phải kiểm tra MSDS để sử dụng, xử lý hóa chất an toàn và phòng ngừa tai nạn."]'::jsonb, 'before_work', 5, '화학물질 MSDS(물질안전보건자료) 확인', 'Kiểm tra MSDS (Bảng dữ liệu an toàn hóa chất)'),
(md5('safety:화학물질을 사용하는 작업 전에는 어떤 보호구를 준비해야 하나요?')::uuid, '화학물질을 사용하는 작업 전에는 어떤 보호구를 준비해야 하나요?', 'Trước khi làm việc với hóa chất, cần chuẩn bị những đồ bảo hộ nào?', '["화학물질을 사용하는 작업 전에서 방독마스크, 화학물질용 보호장갑 등을 준비하고 작업 시 착용합니다.", "화학물질 작업 전 방독마스크와 보호장갑을 착용합니다."]'::jsonb, '["Trước khi làm việc với hóa chất, phải chuẩn bị và đeo mặt nạ phòng độc, găng tay bảo hộ dùng cho hóa chất, v.v.", "Trước khi làm việc với hóa chất, phải đeo mặt nạ phòng độc và găng tay bảo hộ."]'::jsonb, 'before_work', 5, '화학물질 MSDS(물질안전보건자료) 확인', 'Kiểm tra MSDS (Bảng dữ liệu an toàn hóa chất)'),
(md5('safety:화학물질이 무엇인가요?')::uuid, '화학물질이 무엇인가요?', 'Hóa chất là gì?', '["화학물질이란 사업장에서 제품을 만드는 데 사용하는 고체, 액체, 기체로 사람에게 유해하거나 폭발 등의 위험성을 가진 물질입니다.", "사업장에서 사용하는 고체·액체·기체로, 인체에 유해하거나 폭발 등의 위험성이 있는 물질입니다."]'::jsonb, '["Hóa chất là những chất ở dạng rắn, lỏng hoặc khí được sử dụng tại nơi làm việc để sản xuất sản phẩm, có thể gây hại cho con người hoặc có nguy cơ như cháy nổ.", "Là những chất dạng rắn, lỏng hoặc khí được sử dụng tại nơi làm việc, có thể gây hại cho cơ thể người hoặc có nguy cơ cháy nổ."]'::jsonb, 'before_work', 5, '화학물질 MSDS(물질안전보건자료) 확인', 'Kiểm tra MSDS (Bảng dữ liệu an toàn hóa chất)'),
(md5('safety:밀폐공간 작업 전 왜 환기를 해야 할까요?')::uuid, '밀폐공간 작업 전 왜 환기를 해야 할까요?', 'Tại sao phải thông gió trước khi làm việc trong không gian kín?', '["밀폐공간 작업 전 환기 이유는 환기하지 않고 작업을 하면, 유해가스나 산소가 부족하여 작업자가 사망할 위험이 있기 때문입니다.", "유해가스나 산소결핍으로 사고를 예방하기 위해 환기해야 합니다."]'::jsonb, '["Lý do phải thông gió trước khi làm việc trong không gian kín là nếu làm việc mà không thông gió, người lao động có thể tử vong do khí độc hoặc thiếu oxy.", "Phải thông gió để phòng ngừa tai nạn do khí độc hoặc thiếu oxy."]'::jsonb, 'before_work', 6, '밀폐공간 작업 전 환기', 'Thông gió trước khi làm việc trong không gian kín'),
(md5('safety:밀폐공간이 무엇인가요?')::uuid, '밀폐공간이 무엇인가요?', 'Không gian kín là gì?', '["밀폐공간이란 통풍이 불충분하여 산소결핍, 유해가스, 증기 또는 분진이 존재하거나 발생할 우려가 있는 공간입니다.", "밀폐공간은 통풍이 부족하고 산소결핍이나 유해가스가 발생할 수 있는 공간입니다."]'::jsonb, '["Không gian kín là không gian có hệ thống thông gió không đầy đủ, có thể tồn tại hoặc phát sinh tình trạng thiếu oxy, khí độc, hơi hoặc bụi.", "Không gian kín là không gian thông gió không đầy đủ, có thể xảy ra tình trạng thiếu oxy hoặc phát sinh khí độc."]'::jsonb, 'before_work', 6, '밀폐공간 작업 전 환기', 'Thông gió trước khi làm việc trong không gian kín'),
(md5('safety:환기가 무슨 뜻인가요?')::uuid, '환기가 무슨 뜻인가요?', 'Thông gió có nghĩa là gì?', '["환기란 실내의 오염된 공기를 외부의 깨끗한 공기와 교체하여 쾌적하고 안전한 작업환경을 유지하는 행위입니다.", "환기는 오염된 공기를 깨끗한 공기로 바꿔 안전한 작업환경을 유지하는 것입니다."]'::jsonb, '["Thông gió là việc thay thế không khí bị ô nhiễm trong phòng bằng không khí sạch từ bên ngoài để duy trì môi trường làm việc thoải mái và an toàn.", "Thông gió là thay không khí bị ô nhiễm bằng không khí sạch để duy trì môi trường làm việc an toàn."]'::jsonb, 'before_work', 6, '밀폐공간 작업 전 환기', 'Thông gió trước khi làm việc trong không gian kín'),
(md5('safety:가동 중인 기계를 왜 정비하면 안 될까요?')::uuid, '가동 중인 기계를 왜 정비하면 안 될까요?', 'Tại sao không được bảo trì máy móc đang vận hành?', '["가동 중인 기계를 정비하면 안 되는 이유는 정비를 위해 기계 내부에 손이나 머리를 넣게 되는 경우가 많은데 기계가 갑자기 작동하면 사고가 발생할 수 있기 때문입니다.", "정비 중 기계가 갑자기 작동하면 사고가 발생할 수 있기 때문입니다."]'::jsonb, '["Lý do không được bảo trì máy móc đang vận hành là khi bảo trì, thường phải đưa tay hoặc đầu vào bên trong máy, nếu máy đột ngột hoạt động có thể xảy ra tai nạn.", "Vì nếu máy đột ngột hoạt động trong khi đang bảo trì thì có thể xảy ra tai nạn."]'::jsonb, 'during_work', 7, '가동 중인 기계 정비 금지', 'Cấm bảo dưỡng, sửa chữa máy móc khi đang vận hành'),
(md5('safety:가동이 무슨 뜻인가요?')::uuid, '가동이 무슨 뜻인가요?', 'Vận hành là gì?', '["가동이란 생산활동을 위하여 기계, 설비 등을 작동시켜 실제로 운전하거나 운영하는 것입니다.", "가동은 생산을 위해 기계나 설비를 작동하는 것입니다."]'::jsonb, '["Vận hành là việc khởi động máy móc, thiết bị để thực sự vận hành hoặc điều hành nhằm phục vụ hoạt động sản xuất.", "Vận hành là việc khởi động máy móc hoặc thiết bị để phục vụ sản xuất."]'::jsonb, 'during_work', 7, '가동 중인 기계 정비 금지', 'Cấm bảo dưỡng, sửa chữa máy móc khi đang vận hành'),
(md5('safety:기계가 알 수 없는 이유로 멈추면 어떻게 해야 하나요?')::uuid, '기계가 알 수 없는 이유로 멈추면 어떻게 해야 하나요?', 'Nếu máy móc dừng lại vì một lý do không xác định thì phải làm thế nào?', '["기계가 알 수 없는 이유로 멈추면 함부로 조작하지 말고 반장님 등 관리자에게 보고합니다."]'::jsonb, '["Nếu máy móc dừng lại vì một lý do không xác định, không được tự ý thao tác mà phải báo cáo cho quản lý như tổ trưởng."]'::jsonb, 'during_work', 7, '가동 중인 기계 정비 금지', 'Cấm bảo dưỡng, sửa chữa máy móc khi đang vận hành'),
(md5('safety:정비가 무슨 뜻인가요?')::uuid, '정비가 무슨 뜻인가요?', 'Bảo trì có nghĩa là gì?', '["정비란 기계, 설비 등의 이상 여부를 확인하고 고장이나 사고를 예방하기 위해 수리하거나 부품을 교체하는 작업입니다.", "정비는 기계를 점검하고 교체하고 수리하는 작업입니다."]'::jsonb, '["Bảo trì là công việc kiểm tra xem máy móc, thiết bị có bất thường hay không, sửa chữa hoặc thay thế linh kiện để phòng ngừa hỏng hóc và tai nạn.", "Bảo trì là công việc kiểm tra, thay thế và sửa chữa máy móc."]'::jsonb, 'during_work', 7, '가동 중인 기계 정비 금지', 'Cấm bảo dưỡng, sửa chữa máy móc khi đang vận hành'),
(md5('safety:모르는 기계가 무슨 뜻인가요?')::uuid, '모르는 기계가 무슨 뜻인가요?', 'Máy móc không biết sử dụng có nghĩa là gì?', '["모르는 기계란 사용법, 조작 절차 등에 대하여 정확하게 알지 못하여 올바르게 작동시킬 수 없는 설비입니다.", "사용법이나 조작 절차를 몰라 올바르게 작동시킬 수 없는 설비입니다."]'::jsonb, '["Máy móc không biết sử dụng là thiết bị mà người sử dụng không biết chính xác cách sử dụng, quy trình vận hành nên không thể vận hành đúng cách.", "Là thiết bị mà không biết cách sử dụng hoặc quy trình vận hành nên không thể vận hành đúng cách."]'::jsonb, 'during_work', 8, '모르는 기계 임의 조작 금지', 'Cấm tự ý vận hành máy móc khi chưa biết cách sử dụng'),
(md5('safety:모르는 기계를 왜 임의로 조작하면 안 될까요?')::uuid, '모르는 기계를 왜 임의로 조작하면 안 될까요?', 'Tại sao không được tự ý thao tác với máy móc mà mình không biết sử dụng?', '["모르는 기계를 임의 조작하면 안 되는 이유는 기계가 갑자기 작동하거나 예상하지 못한 동작이 발생하면 작업자와 동료에게 사고가 발생할 수 있기 때문입니다.", "기계가 갑자기 작동하거나 예상하지 못한 동작으로 사고가 발생할 수 있기 때문입니다."]'::jsonb, '["Lý do không được tự ý thao tác với máy móc mà mình không biết sử dụng là vì nếu máy đột ngột hoạt động hoặc xảy ra những chuyển động không thể lường trước, có thể gây tai nạn cho người lao động và đồng nghiệp.", "Vì máy có thể đột ngột hoạt động hoặc xảy ra những chuyển động không thể lường trước, dẫn đến tai nạn."]'::jsonb, 'during_work', 8, '모르는 기계 임의 조작 금지', 'Cấm tự ý vận hành máy móc khi chưa biết cách sử dụng'),
(md5('safety:비상정지장치가 무엇인가요?')::uuid, '비상정지장치가 무엇인가요?', 'Thiết bị dừng khẩn cấp là gì?', '["위험한 상황이 발생하거나 기계를 긴급하게 멈춰야 할 경우 정지시키는 버튼을 비상정지장치라고 합니다.", "비상정지장치는 위험하거나 긴급한 상황에서 기계를 멈추는 버튼입니다."]'::jsonb, '["Nút dùng để dừng máy khi xảy ra tình huống nguy hiểm hoặc cần dừng máy khẩn cấp được gọi là thiết bị dừng khẩn cấp.", "Thiết bị dừng khẩn cấp là nút dùng để dừng máy trong tình huống nguy hiểm hoặc khẩn cấp."]'::jsonb, 'during_work', 8, '모르는 기계 임의 조작 금지', 'Cấm tự ý vận hành máy móc khi chưa biết cách sử dụng'),
(md5('safety:임의 조작이 무슨 뜻인가요?')::uuid, '임의 조작이 무슨 뜻인가요?', 'Tự ý thao tác là gì?', '["임의 조작이란 지정된 절차나 허가 없이 기계나 설비를 마음대로 조작하거나 변경하는 행위입니다.", "임의 조작은 허가 없이 기계를 조작하거나 변경하는 것입니다."]'::jsonb, '["Tự ý thao tác là hành vi tự ý vận hành hoặc thay đổi máy móc, thiết bị mà không có sự cho phép hoặc không tuân theo quy trình đã quy định.", "Tự ý thao tác là việc vận hành hoặc thay đổi máy móc mà không được phép."]'::jsonb, 'during_work', 8, '모르는 기계 임의 조작 금지', 'Cấm tự ý vận hành máy móc khi chưa biết cách sử dụng'),
(md5('safety:기계의 안전장치를 해체하고 작업하면 어떤 위험이 있나요?')::uuid, '기계의 안전장치를 해체하고 작업하면 어떤 위험이 있나요?', 'Nếu tháo dỡ thiết bị an toàn của máy móc rồi làm việc thì có những nguy hiểm gì?', '["안전장치를 해체하고 작업하면 기계에 끼일 수 있습니다."]'::jsonb, '["Nếu tháo dỡ thiết bị an toàn rồi làm việc, có thể bị cuốn hoặc kẹt vào máy móc."]'::jsonb, 'during_work', 9, '안전장치·시설 해체·해지 금지', 'Cấm tháo dỡ hoặc vô hiệu hóa thiết bị, công trình an toàn'),
(md5('safety:안전장치·시설을 왜 해체·해지하면 안 될까요?')::uuid, '안전장치·시설을 왜 해체·해지하면 안 될까요?', 'Tại sao không được tháo dỡ hoặc vô hiệu hóa thiết bị, lắp đặt an toàn?', '["안전장치·시설을 해체·해지하면 안 되는 이유는 안전장치·시설을 해체·해지하면 기계가 고장나거나 사람이 실수했을 때 사고를 막아줄 수 없기 때문입니다.", "기계가 고장나거나 사람이 실수했을 때 사고를 막을 수 없기 때문입니다."]'::jsonb, '["Lý do không được tháo dỡ hoặc vô hiệu hóa thiết bị, lắp đặt an toàn là vì nếu tháo dỡ hoặc vô hiệu hóa, khi máy móc bị hỏng hoặc người lao động mắc sai sót thì không thể ngăn ngừa tai nạn.", "Vì khi máy móc bị hỏng hoặc người lao động mắc sai sót thì không thể ngăn ngừa tai nạn."]'::jsonb, 'during_work', 9, '안전장치·시설 해체·해지 금지', 'Cấm tháo dỡ hoặc vô hiệu hóa thiết bị, công trình an toàn'),
(md5('safety:안전장치·시설이 무엇인지 알고 있나요?')::uuid, '안전장치·시설이 무엇인지 알고 있나요?', 'Bạn có biết thiết bị an toàn - lắp đặt an toàn là gì không?', '["안전장치·시설이란 기계나 설비를 사용하는 작업자를 사고로부터 보호하기 위해 설치하는 보호설비입니다."]'::jsonb, '["Bạn có biết thiết bị an toàn - lắp đặt an toàn các thiết bị bảo vệ được lắp đặt nhằm bảo vệ người lao động sử dụng máy móc hoặc thiết bị khỏi tai nạn."]'::jsonb, 'during_work', 9, '안전장치·시설 해체·해지 금지', 'Cấm tháo dỡ hoặc vô hiệu hóa thiết bị, công trình an toàn'),
(md5('safety:해체·해지가 무슨 뜻인지 알고 있나요?')::uuid, '해체·해지가 무슨 뜻인지 알고 있나요?', 'Bạn có biết “tháo dỡ · tháo bỏ” có nghĩa là gì không?', '["해체·해지란 기계, 장치, 구조물 등을 원래 상태에서 분리하거나 안전기능 등을 정지시키는 것입니다."]'::jsonb, '["Tháo dỡ · tháo bỏ là việc tháo tách máy móc, thiết bị, kết cấu... khỏi trạng thái ban đầu hoặc dừng các chức năng an toàn."]'::jsonb, 'during_work', 9, '안전장치·시설 해체·해지 금지', 'Cấm tháo dỡ hoặc vô hiệu hóa thiết bị, công trình an toàn'),
(md5('safety:기계 작업 시 보조 도구를 사용하는 이유를 알고 있나요?')::uuid, '기계 작업 시 보조 도구를 사용하는 이유를 알고 있나요?', 'Bạn có biết lý do sử dụng dụng cụ hỗ trợ khi làm việc với máy móc không?', '["기계 작업 시 손이 끼이는 사고 등을 예방하기 위해 보조 도구를 사용합니다."]'::jsonb, '["Khi làm việc với máy móc, sử dụng dụng cụ hỗ trợ để phòng ngừa các tai nạn như bị kẹt tay vào máy."]'::jsonb, 'during_work', 10, '지정된 보조 도구·공구 사용', 'Sử dụng đúng dụng cụ hỗ trợ và dụng cụ được chỉ định'),
(md5('safety:보조 도구·공구가 무엇인가요?')::uuid, '보조 도구·공구가 무엇인가요?', 'Dụng cụ hỗ trợ · dụng cụ cầm tay là gì?', '["보조 도구·공구란 작업자가 작업을 할 때 사고를 방지하기 위하여 보완적으로 사용하는 장비나 기구입니다."]'::jsonb, '["Dụng cụ hỗ trợ · dụng cụ cầm tay là các thiết bị hoặc dụng cụ được người lao động sử dụng để hỗ trợ trong quá trình làm việc nhằm phòng ngừa tai nạn."]'::jsonb, 'during_work', 10, '지정된 보조 도구·공구 사용', 'Sử dụng đúng dụng cụ hỗ trợ và dụng cụ được chỉ định'),
(md5('safety:작업 시 왜 지정된 보조 도구·공구를 사용해야 할까요?')::uuid, '작업 시 왜 지정된 보조 도구·공구를 사용해야 할까요?', 'Tại sao khi làm việc phải sử dụng dụng cụ hỗ trợ · dụng cụ cầm tay được chỉ định?', '["작업 시 지정된 보조 도구·공구를 사용해야 하는 이유는 각 도구·공구는 특정 용도에 맞게 제작되어 있어 목적에 맞지 않게 사용하면 파손되거나 사고의 위험이 있기 때문입니다.", "목적에 맞지 않게 사용하면 파손되거나 사고가 발생할 수 있기 때문입니다."]'::jsonb, '["Lý do phải sử dụng dụng cụ hỗ trợ · dụng cụ cầm tay được chỉ định khi làm việc là mỗi dụng cụ được chế tạo phù hợp với một mục đích cụ thể, nếu sử dụng không đúng mục đích có thể bị hư hỏng hoặc gây ra tai nạn.", "Nếu sử dụng không đúng mục đích, dụng cụ có thể bị hư hỏng hoặc gây ra tai nạn."]'::jsonb, 'during_work', 10, '지정된 보조 도구·공구 사용', 'Sử dụng đúng dụng cụ hỗ trợ và dụng cụ được chỉ định'),
(md5('safety:지정이 무슨 뜻인지 알고 있나요?')::uuid, '지정이 무슨 뜻인지 알고 있나요?', 'Chỉ định có nghĩa là gì?', '["지정이란 사고를 방지하기 위해 사람이나 사물, 장소 등을 공식적으로 정해 놓는 것입니다."]'::jsonb, '["Chỉ định là việc chính thức quy định người, vật, địa điểm... nhằm phòng ngừa tai nạn."]'::jsonb, 'during_work', 10, '지정된 보조 도구·공구 사용', 'Sử dụng đúng dụng cụ hỗ trợ và dụng cụ được chỉ định'),
(md5('safety:시야 확보는 무슨 뜻인가요?')::uuid, '시야 확보는 무슨 뜻인가요?', 'Đảm bảo tầm nhìn là gì?', '["시야 확보란 지게차 운전자가 앞, 옆 및 뒤쪽의 작업자, 장애물, 경사 등을 명확하게 확인하며 운전하는 것입니다.", "시야 확보는 앞, 옆, 뒤의 작업자와 장애물을 확인하며 운전하는 것입니다."]'::jsonb, '["Đảm bảo tầm nhìn là việc người lái xe nâng xác nhận rõ ràng công nhân, chướng ngại vật phía trước, bên cạnh và phía sau trước khi vận hành.", "Đảm bảo tầm nhìn là kiểm tra rõ công nhân và chướng ngại vật phía trước, bên cạnh và phía sau rồi mới vận hành."]'::jsonb, 'during_work', 11, '지게차 운전 시 안전벨트 착용 및 시야 확보', 'Khi vận hành xe nâng, phải thắt dây an toàn và đảm bảo tầm nhìn'),
(md5('safety:안전벨트가 무엇인가요?')::uuid, '안전벨트가 무엇인가요?', 'Dây an toàn là gì?', '["안전벨트란 지게차 운전자가 충돌, 급정지, 넘어짐 등에 의하여 몸이 튕겨 나가는 것을 방지하기 위하여 착용하는 보호장비입니다.", "안전벨트는 몸이 튕겨 나가는 것을 막는 보호장비입니다."]'::jsonb, '["Dây an toàn là thiết bị bảo hộ được đeo để ngăn cơ thể người lái bị va đập, dừng đột ngột hoặc bị văng ra ngoài.", "Dây an toàn là thiết bị bảo hộ ngăn cơ thể bị văng ra ngoài."]'::jsonb, 'during_work', 11, '지게차 운전 시 안전벨트 착용 및 시야 확보', 'Khi vận hành xe nâng, phải thắt dây an toàn và đảm bảo tầm nhìn'),
(md5('safety:지게차 운전 시 왜 안전벨트를 착용하고 시야를 확보해야 할까요?')::uuid, '지게차 운전 시 왜 안전벨트를 착용하고 시야를 확보해야 할까요?', 'Tại sao khi vận hành xe nâng phải thắt dây an toàn và đảm bảo tầm nhìn?', '["지게차 운전 시 안전벨트 착용 및 시야 확보 이유는 안전벨트를 착용하고 시야를 확보하면 지게차 작업 중 운전자 및 동료의 사고를 막을 수 있기 때문입니다.", "운전자와 동료의 사고를 예방하기 때문입니다."]'::jsonb, '["Lý do phải thắt dây an toàn và đảm bảo tầm nhìn khi vận hành xe nâng là nếu thắt dây an toàn và đảm bảo tầm nhìn thì có thể ngăn ngừa tai nạn cho người lái trong quá trình vận hành xe nâng.", "Vì có thể phòng ngừa tai nạn cho người lái và đồng nghiệp."]'::jsonb, 'during_work', 11, '지게차 운전 시 안전벨트 착용 및 시야 확보', 'Khi vận hành xe nâng, phải thắt dây an toàn và đảm bảo tầm nhìn'),
(md5('safety:지게차가 무엇인가요?')::uuid, '지게차가 무엇인가요?', '→ Xe nâng là gì?', '["지게차란 무거운 화물이나 자재를 들어 올려 운반하거나 적재하는 데 사용하는 운반용 기계입니다."]'::jsonb, '["Xe nâng là máy vận chuyển dùng để nâng, vận chuyển hoặc xếp dỡ hàng hóa, vật liệu."]'::jsonb, 'during_work', 11, '지게차 운전 시 안전벨트 착용 및 시야 확보', 'Khi vận hành xe nâng, phải thắt dây an toàn và đảm bảo tầm nhìn'),
(md5('safety:지게차를 운전할 수 있나요? 지게차는 누가 운전할 수 있나요?')::uuid, '지게차를 운전할 수 있나요? 지게차는 누가 운전할 수 있나요?', 'Ai có thể lái xe nâng?', '["대한민국에서 지게차는 자격이 있는 사람만이 운전할 수 있습니다. 아무나 운전할 수 없습니다.", "지게차는 자격 소지자만 운전 가능합니다."]'::jsonb, '["Tại Hàn Quốc chỉ người có giấy phép/chứng chỉ đủ điều kiện mới được lái xe nâng. Không phải ai cũng có thể lái.", "Xe nâng chỉ người có bằng/chứng chỉ mới được lái."]'::jsonb, 'during_work', 11, '지게차 운전 시 안전벨트 착용 및 시야 확보', 'Khi vận hành xe nâng, phải thắt dây an toàn và đảm bảo tầm nhìn'),
(md5('safety:2 인1 조 작업이 무엇인가요?')::uuid, '2인1조 작업이 무엇인가요?', 'Công việc 2 người 1 nhóm là gì?', '["2인1조 작업이란 한 명이 작업을 수행할 때 다른 한 명은 주변을 감시하거나 이상 상황 발생 시 즉시 조치할 수 있도록 함께 작업을 하는 것입니다.", "2인1조 작업은 한 명은 작업하고, 다른 한 명은 주변을 확인하고 이상 시 조치하는 것입니다."]'::jsonb, '["Công việc 2 người 1 nhóm là khi một người thực hiện công việc thì người còn lại cùng làm việc để giám sát xung quanh hoặc có thể xử lý ngay lập tức khi xảy ra tình huống bất thường.", "Là việc một người làm việc, người còn lại kiểm tra xung quanh và xử lý khi có bất thường."]'::jsonb, 'during_work', 12, '위험작업은 2인1조 작업', 'Công việc nguy hiểm phải thực hiện theo nhóm 2 người'),
(md5('safety:사다리 위에서 혼자 작업할 수 있나요?')::uuid, '사다리 위에서 혼자 작업할 수 있나요?', 'Có thể làm việc một mình trên thang không?', '["사다리 위에서는 전구를 교체하는 것과 같이 간단한 작업만 할 수 있으며, 한 사람은 아래에서 사다리를 잡아줘야 합니다.", "사다리에서는 간단한 작업만 하고, 한 사람은 아래에서 사다리를 잡아야 합니다."]'::jsonb, '["Trên thang chỉ được thực hiện những công việc đơn giản; đồng thời có một người phải đứng phía dưới giữ thang.", "Trên thang một người làm công việc đơn giản, một người phải giữ thang từ phía dưới."]'::jsonb, 'during_work', 12, '위험작업은 2인1조 작업', 'Công việc nguy hiểm phải thực hiện theo nhóm 2 người'),
(md5('safety:위험작업은 왜 2 인1 조로 해야 할까요?')::uuid, '위험작업은 왜 2인1조로 해야 할까요?', 'Tại sao công việc nguy hiểm phải thực hiện theo nhóm 2 người?', '["위험작업을 2인1조로 해야 하는 이유는 작업자의 상태를 실시간으로 감시하고 보호할 수 있으며 사고 발생 시 즉각적인 구조와 대응이 가능하기 때문입니다.", "작업자의 상태를 확인하고 사고 발생 시 즉시 구조하고 대응할 수 있기 때문입니다."]'::jsonb, '["Lý do công việc nguy hiểm phải thực hiện theo nhóm 2 người là có thể theo dõi tình trạng của người đang làm việc trong thời gian thực và nhanh chóng cứu giúp khi xảy ra tai nạn.", "Có thể kiểm tra tình trạng của người lao động và nhanh chóng cứu giúp khi xảy ra tai nạn."]'::jsonb, 'during_work', 12, '위험작업은 2인1조 작업', 'Công việc nguy hiểm phải thực hiện theo nhóm 2 người'),
(md5('safety:위험작업이 무엇인가요?')::uuid, '위험작업이 무엇인가요?', 'Công việc nguy hiểm là gì?', '["위험작업이란 작업자의 신체 또는 생명에 위험을 받을 수 있는 위험요인이 존재하거나 사고 발생 가능성이 높은 작업입니다.", "작업자의 신체 또는 생명에 위험요인이 있는 작업입니다."]'::jsonb, '["Công việc nguy hiểm là công việc có yếu tố nguy hiểm đối với cơ thể hoặc tính mạng của người lao động, hoặc có khả năng cao xảy ra tai nạn.", "Là công việc có yếu tố nguy hiểm đối với cơ thể hoặc tính mạng của người lao động."]'::jsonb, 'during_work', 12, '위험작업은 2인1조 작업', 'Công việc nguy hiểm phải thực hiện theo nhóm 2 người'),
(md5('safety:근처에서 중장비가 작업을 하고 있으면 어떻게 해야 하나요?')::uuid, '근처에서 중장비가 작업을 하고 있으면 어떻게 해야 하나요?', 'Nếu gần đó đang có máy móc hạng nặng làm việc thì phải làm thế nào?', '["중장비가 작업하고 있는 작업 구역은 접근하지 않아야 합니다. 중장비 작업구역은 접근 금지 구역입니다.", "중장비 작업구역은 접근 금지 구역이니까 접근하지 않아야 합니다"]'::jsonb, '["Không được tiếp cận khu vực đang có máy móc hạng nặng làm việc. Khu vực làm việc của máy móc hạng nặng là khu vực cấm tiếp cận.", "Vì khu vực làm việc của máy móc hạng nặng là khu vực cấm tiếp cận, nên không được tiếp cận."]'::jsonb, 'during_work', 13, '중장비 작업구역 접근 금지', 'Cấm tiếp cận khu vực làm việc của máy móc hạng nặng'),
(md5('safety:작업구역이 무엇인가요?')::uuid, '작업구역이 무엇인가요?', 'Khu vực làm việc là gì?', '["작업구역이란 특정 작업이 이루어지는 공간으로 작업자가 실제로 일하거나 중장비가 작동하는 구역으로 사고 위험이 있는 영역입니다.", "작업자가 실제로 일하거나 중장비가 작동하는 구역입니다."]'::jsonb, '["Khu vực làm việc là không gian diễn ra một công việc cụ thể, nơi người lao động thực sự làm việc hoặc nơi thiết bị hạng nặng hoạt động.", "Là khu vực người lao động thực hiện công việc hoặc nơi thiết bị hạng nặng hoạt động."]'::jsonb, 'during_work', 13, '중장비 작업구역 접근 금지', 'Cấm tiếp cận khu vực làm việc của máy móc hạng nặng'),
(md5('safety:중장비 작업구역은 왜 접근 금지 할까요?')::uuid, '중장비 작업구역은 왜 접근 금지 할까요?', 'Tại sao cấm tiếp cận khu vực làm việc của thiết bị hạng nặng?', '["중장비 작업구역을 접근 금지 하는 이유는 중장비는 운전석에서 보지 못하는 공간이 매우 넓어 작업구역에 무단으로 접근하면 사망사고 발생 위험이 매우 높기 때문입니다.", "운전석에서 보지 못하는 공간이 있어 사고 위험이 높기 때문입니다."]'::jsonb, '["Lý do cấm tiếp cận khu vực làm việc của thiết bị hạng nặng là vì máy móc hạng nặng có không gian rất rộng mà người lái không thể quan sát được, vì vậy nếu tự ý đi vào khu vực làm việc thì nguy cơ xảy ra tai nạn chết người rất cao.", "Vì có những khu vực không thể nhìn thấy từ ghế lái, nên nguy cơ xảy ra tai nạn cao."]'::jsonb, 'during_work', 13, '중장비 작업구역 접근 금지', 'Cấm tiếp cận khu vực làm việc của máy móc hạng nặng'),
(md5('safety:중장비가 무엇인가요?')::uuid, '중장비가 무엇인가요?', 'Thiết bị hạng nặng là gì?', '["중장비란 크기와 중량이 크고 흙 운반, 땅 파기 등 대형 작업을 수행하기 위한 기계장비입니다."]'::jsonb, '["Thiết bị hạng nặng là máy móc được sử dụng để thực hiện các công việc lớn như vận chuyển, đào đất, có kích thước và trọng lượng lớn."]'::jsonb, 'during_work', 13, '중장비 작업구역 접근 금지', 'Cấm tiếp cận khu vực làm việc của máy móc hạng nặng'),
(md5('safety:불에 잘 타는 물건이 근처에 있으면 용접작업 전에 어떻게 해야 하나요?')::uuid, '불에 잘 타는 물건이 근처에 있으면 용접작업 전에 어떻게 해야 하나요?', 'Nếu vật dễ cháy ở gần, trước khi tiến hành công việc hàn thì phải làm gì?', '["불에 잘 타는 물건을 다른 곳으로 치운 후 작업해야 합니다."]'::jsonb, '["Phải di chuyển các vật dễ cháy sang nơi khác rồi mới tiến hành công việc."]'::jsonb, 'during_work', 14, '화재 가능 물질 주변 화기 금지', 'Cấm sử dụng nguồn lửa gần các vật liệu có nguy cơ cháy'),
(md5('safety:불이 났을 때는 어떻게 해야 하나요?')::uuid, '불이 났을 때는 어떻게 해야 하나요?', 'Khi xảy ra hỏa hoạn thì phải làm gì?', '["일반적인 화재 시 소화기를 사용하여 불을 끄거나 불을 끌 수 없을 때는 즉시 비상구로 대피해야 합니다.", "소화기로 불을 끄고, 끌 수 없으면 비상구로 대피합니다."]'::jsonb, '["Khi xảy ra hỏa hoạn thông thường, dùng bình chữa cháy để dập lửa; nếu không thể dập được lửa thì phải lập tức sơ tán qua lối thoát hiểm.", "Dùng bình chữa cháy để dập lửa, nếu không dập được thì sơ tán qua lối thoát hiểm."]'::jsonb, 'during_work', 14, '화재 가능 물질 주변 화기 금지', 'Cấm sử dụng nguồn lửa gần các vật liệu có nguy cơ cháy'),
(md5('safety:화기가 무엇인지 알고 있나요?')::uuid, '화기가 무엇인지 알고 있나요?', 'Bạn có biết nguồn lửa là gì không?', '["화기란 작업 현장에서 불꽃, 불티, 열을 발생시킬 수 있는 모든 기구와 장치입니다."]'::jsonb, '["Nguồn lửa là tất cả các dụng cụ và thiết bị tại nơi làm việc có thể tạo ra tia lửa, đốm lửa hoặc nhiệt."]'::jsonb, 'during_work', 14, '화재 가능 물질 주변 화기 금지', 'Cấm sử dụng nguồn lửa gần các vật liệu có nguy cơ cháy'),
(md5('safety:화재 가능 물질 주변에서 왜 화기를 금지 할까요?')::uuid, '화재 가능 물질 주변에서 왜 화기를 금지 할까요?', 'Tại sao cấm sử dụng nguồn lửa xung quanh các vật liệu có nguy cơ cháy?', '["화재 가능 물질 주변에서 화기를 금지하는 이유는 화재 가능 물질이 주변에 있는 상황에서 화기를 사용하면 화재가 발생할 위험이 크기 때문입니다.", "화재가 발생할 위험이 크기 때문입니다."]'::jsonb, '["Lý do cấm sử dụng nguồn lửa xung quanh các vật liệu có nguy cơ cháy là: Khi sử dụng nguồn lửa trong tình huống có vật liệu dễ cháy ở xung quanh thì nguy cơ xảy ra hỏa hoạn rất cao.", "Vì nguy cơ xảy ra hỏa hoạn rất cao."]'::jsonb, 'during_work', 14, '화재 가능 물질 주변 화기 금지', 'Cấm sử dụng nguồn lửa gần các vật liệu có nguy cơ cháy'),
(md5('safety:화재가 무엇인지 알고 있나요?')::uuid, '화재가 무엇인지 알고 있나요?', 'Bạn có biết hỏa hoạn là gì không?', '["화재란 탈 수 있는 물질이 공기 중의 산소와 불꽃 등을 만나 열과 빛을 내며 타는 것입니다."]'::jsonb, '["Hỏa hoạn là hiện tượng vật liệu có thể cháy gặp oxy trong không khí và lửa, tạo ra nhiệt và ánh sáng rồi cháy."]'::jsonb, 'during_work', 14, '화재 가능 물질 주변 화기 금지', 'Cấm sử dụng nguồn lửa gần các vật liệu có nguy cơ cháy'),
(md5('safety:화학물질 취급 시 왜 환기장치를 가동해야 할까요?')::uuid, '화학물질 취급 시 왜 환기장치를 가동해야 할까요?', 'Tại sao khi xử lý hóa chất phải vận hành thiết bị thông gió?', '["화학물질 취급 시 환기장치를 가동하는 이유는 화학물질은 눈에 보이지 않는 유해 증기, 가스, 분진 등을 방출하는 경우가 많아 즉시 외부로 배출하지 않으면 건강에 해롭기 때문입니다.", "유해물질을 밖으로 배출하여 건강을 보호하기 때문입니다."]'::jsonb, '["Lý do phải vận hành thiết bị thông gió khi xử lý hóa chất là: Hóa chất thường phát sinh hơi độc, khí độc, bụi... không nhìn thấy được, nếu không nhanh chóng thải ra ngoài thì có thể gây hại cho sức khỏe.", "Vì để thải các chất có hại ra bên ngoài bảo vệ sức khỏe."]'::jsonb, 'during_work', 15, '화학물질 작업 시 환기장치 가동', 'Khi làm việc với hóa chất, phải vận hành hệ thống thông gió'),
(md5('safety:화학물질을 다룰 때는 어떻게 해야 하나요?')::uuid, '화학물질을 다룰 때는 어떻게 해야 하나요?', 'Khi xử lý hóa chất thì phải làm như thế nào?', '["화학물질을 다룰 때는 환기장치를 가동해야 하고, 방독마스크, 화학물질용 보호장갑 등 보호구를 착용해야 합니다.", "환기장치를 가동하고 보호구를 착용해야 합니다."]'::jsonb, '["Khi xử lý hóa chất, phải vận hành thiết bị thông gió và đeo các phương tiện bảo hộ như mặt nạ phòng độc, găng tay bảo hộ dùng cho hóa chất.", "Phải vận hành thiết bị thông gió và đeo đồ bảo hộ."]'::jsonb, 'during_work', 15, '화학물질 작업 시 환기장치 가동', 'Khi làm việc với hóa chất, phải vận hành hệ thống thông gió'),
(md5('safety:15:화학물질이 무엇인가요?')::uuid, '화학물질이 무엇인가요?', 'Hóa chất là gì?', '["화학물질이란 사업장에서 물건을 만드는 데 사용하는 고체, 액체, 기체로 사람에게 유해하거나 폭발 등의 위험성을 가진 물질입니다.", "사업장에서 사용하는 고체·액체·기체로, 인체에 유해하거나 폭발 등의 위험성이 있는 물질입니다."]'::jsonb, '["Hóa chất là những chất ở dạng rắn, lỏng hoặc khí được sử dụng để sản xuất, chế tạo sản phẩm tại nơi làm việc và có thể gây hại cho con người hoặc có nguy cơ cháy nổ.", "Là những chất rắn, lỏng hoặc khí được sử dụng tại nơi làm việc, có thể gây hại cho cơ thể con người hoặc có nguy cơ cháy nổ."]'::jsonb, 'during_work', 15, '화학물질 작업 시 환기장치 가동', 'Khi làm việc với hóa chất, phải vận hành hệ thống thông gió'),
(md5('safety:환기장치가 무엇인가요?')::uuid, '환기장치가 무엇인가요?', 'Thiết bị thông gió là gì?', '["환기장치란 실내의 유해물질을 제거하고 신선한 외부 공기를 내부로 공급하여 쾌적하고 안전하게 작업환경을 유지하는 설비입니다.", "환기장치는 유해물질을 제거하고 깨끗한 공기를 공급하는 설비입니다."]'::jsonb, '["Thiết bị thông gió là thiết bị giúp loại bỏ các chất có hại trong phòng, cung cấp không khí trong lành từ bên ngoài vào và duy trì môi trường làm việc thoải mái, an toàn.", "Thiết bị thông gió là thiết bị loại bỏ các chất có hại và cung cấp không khí sạch."]'::jsonb, 'during_work', 15, '화학물질 작업 시 환기장치 가동', 'Khi làm việc với hóa chất, phải vận hành hệ thống thông gió'),
(md5('safety:출입 금지라는 뜻을 알고 있나요?')::uuid, '출입 금지라는 뜻을 알고 있나요?', 'Bạn có biết “cấm ra vào” có nghĩa là gì không?', '["사고 위험이 높아 아무나 들어가면 안되는 곳을 출입 금지라고 표시합니다.", "사고 위험이 높아 아무나 들어가면 안 되는 곳입니다."]'::jsonb, '["Những nơi có nguy cơ xảy ra tai nạn cao, không phải ai cũng được phép vào, sẽ được đánh dấu là “cấm ra vào”.", "Đây là nơi có nguy cơ xảy ra tai nạn cao nên không phải ai cũng được phép vào."]'::jsonb, 'during_work', 16, '통제구역 허가 없이 출입 금지', 'Cấm ra vào khu vực kiểm soát khi chưa được phép'),
(md5('safety:통제 구역이 무엇인가요?')::uuid, '통제 구역이 무엇인가요?', 'Khu vực kiểm soát là gì?', '["통제구역이란 위험요인이 있거나 사고가 발생하는 공간입니다."]'::jsonb, '["Khu vực kiểm soát là không gian có các yếu tố nguy hiểm hoặc nơi có thể xảy ra tai nạn."]'::jsonb, 'during_work', 16, '통제구역 허가 없이 출입 금지', 'Cấm ra vào khu vực kiểm soát khi chưa được phép'),
(md5('safety:통제구역은 왜 허가 없이 출입 금지 할까요?')::uuid, '통제구역은 왜 허가 없이 출입 금지 할까요?', 'Tại sao khu vực kiểm soát lại cấm ra vào nếu không có sự cho phép?', '["통제구역을 허가 없이 출입 금지 하는 이유는 통제구역은 일반구역보다 사고 위험이 높아 허가 없이 들어가는 것은 안전조치 없이 위험에 노출되는 것과 같기 때문입니다.", "통제구역은 사고 위험이 높아 허가 없이 들어가면 위험에 노출될 수 있기 때문입니다."]'::jsonb, '["Lý do cấm ra vào khu vực kiểm soát khi chưa được phép là: Khu vực kiểm soát có nguy cơ xảy ra tai nạn cao hơn khu vực thông thường, nên việc tự ý đi vào khi chưa được phép cũng giống như tiếp xúc với nguy hiểm mà không có biện pháp an toàn.", "Vì khu vực kiểm soát có nguy cơ xảy ra tai nạn cao, nên nếu vào mà không được phép thì có thể tiếp xúc với nguy hiểm."]'::jsonb, 'during_work', 16, '통제구역 허가 없이 출입 금지', 'Cấm ra vào khu vực kiểm soát khi chưa được phép'),
(md5('safety:허가가 무슨 뜻인가요?')::uuid, '허가가 무슨 뜻인가요?', 'Đồng ý/ cho phép có nghĩa là gì?', '["허가란 위험하거나 특별한 자격이 필요한 작업에 대하여 작업 전에 안전조건을 확인하고 그 조건을 충족했을 경우 작업 수행을 승인하는 것입니다.", "허가란 작업 전 안전 조건을 확인하여 위험·특수 작업의 수행을 승인하는 것입니다."]'::jsonb, '["“Đồng ý/ cho phép” là việc kiểm tra các điều kiện an toàn trước khi thực hiện những công việc nguy hiểm hoặc yêu cầu trình độ/điều kiện đặc biệt, và chỉ cho phép thực hiện công việc khi các điều kiện đó được đáp ứng.", "“Đồng ý/ cho phép” là việc kiểm tra các điều kiện an toàn trước khi làm việc rồi phê duyệt cho phép thực hiện các công việc nguy hiểm hoặc công việc đặc biệt."]'::jsonb, 'during_work', 16, '통제구역 허가 없이 출입 금지', 'Cấm ra vào khu vực kiểm soát khi chưa được phép'),
(md5('safety:무거운 물건은 어떻게 들어야 하나요?')::uuid, '무거운 물건은 어떻게 들어야 하나요?', 'Vật nặng thì nên nâng như thế nào?', '["무거운 물건은 두 사람 이상이 들거나 장비를 사용해야 하며, 혼자 들 수 있는 경우에는 허리를 펴고 다리의 힘으로 들어야 합니다.", "두 사람 이상이 들거나 장비를 사용하고, 혼자 들 때는 허리를 펴고 다리 힘으로 들어야 합니다."]'::jsonb, '["Vật nặng nên được hai người trở lên cùng nâng hoặc sử dụng thiết bị hỗ trợ. Nếu có thể tự mình nâng thì phải giữ lưng thẳng và dùng sức của chân để nâng.", "Nên hai người trở lên cùng nâng hoặc sử dụng thiết bị hỗ trợ; nếu nâng một mình thì phải giữ lưng thẳng và dùng sức của chân để nâng."]'::jsonb, 'during_work', 17, '중량물 들기는 허리 펴고 다리 힘 이용', 'Khi nâng vật nặng, giữ thẳng lưng và dùng sức của chân'),
(md5('safety:중량물 들기는 왜 허리 펴고 다리 힘을 이용해야 할까요?')::uuid, '중량물 들기는 왜 허리 펴고 다리 힘을 이용해야 할까요?', 'Tại sao khi nâng vật nặng phải giữ lưng thẳng và dùng sức của chân?', '["중량물을 들 때 허리 펴고 다리 힘을 이용해야 하는 이유는 허리를 펴고 몸에서 가장 크고 강한 다리 근육을 사용하여 물건을 들어야 허리를 다치지 않을 수 있기 때문입니다.", "몸에서 가장 크고 강한 다리 근육을 사용하여 물건을 들어야 허리를 다치지 않을 수 있기 때문입니다."]'::jsonb, '["Vì khi nâng vật nặng, giữ lưng thẳng và dùng các cơ chân khỏe nhất của cơ thể để nâng vật sẽ giúp tránh làm tổn thương lưng.", "Cơ chân là cơ khỏe nhất của cơ thể nên khi nâng vật cps thể tránh tổn thương đến lưng"]'::jsonb, 'during_work', 17, '중량물 들기는 허리 펴고 다리 힘 이용', 'Khi nâng vật nặng, giữ thẳng lưng và dùng sức của chân'),
(md5('safety:중량물이 무엇인지 알고 있나요?')::uuid, '중량물이 무엇인지 알고 있나요?', 'Bạn có biết vật nặng là gì không?', '["중량물이란 무겁고 사람이 쉽게 들거나 옮기기 어려운 물체로 운반 시 특별한 취급주의가 필요한 물건입니다."]'::jsonb, '["Vật nặng là những vật thể nặng, con người khó có thể dễ dàng nâng hoặc di chuyển, và cần đặc biệt chú ý khi vận chuyển, bốc dỡ."]'::jsonb, 'during_work', 17, '중량물 들기는 허리 펴고 다리 힘 이용', 'Khi nâng vật nặng, giữ thẳng lưng và dùng sức của chân'),
(md5('safety:무거운 물건을 옮길 때에는 어떻게 해야 하나요?')::uuid, '무거운 물건을 옮길 때에는 어떻게 해야 하나요?', 'Khi di chuyển vật nặng thì phải làm như thế nào?', '["무거운 물건을 옮길 때에는 운반기구를 사용합니다."]'::jsonb, '["Khi di chuyển vật nặng sử dụng dụng cụ vận chuyển."]'::jsonb, 'during_work', 18, '중량물 운반 시 운반기구 활용', 'Khi vận chuyển vật nặng, phải sử dụng dụng cụ hỗ trợ vận chuyển'),
(md5('safety:운반 기구가 무엇인가요?')::uuid, '운반 기구가 무엇인가요?', 'Dụng cụ vận chuyển là gì?', '["운반 기구란 작업자가 물건이나 자재를 보다 안전하고 효율적으로 옮기기 위해 사용하는 도구나 장비입니다."]'::jsonb, '["Dụng cụ vận chuyển là những công cụ hoặc thiết bị mà người lao động sử dụng để di chuyển đồ vật hoặc vật liệu một cách an toàn và hiệu quả hơn."]'::jsonb, 'during_work', 18, '중량물 운반 시 운반기구 활용', 'Khi vận chuyển vật nặng, phải sử dụng dụng cụ hỗ trợ vận chuyển'),
(md5('safety:운반이 무엇인가요?')::uuid, '운반이 무엇인가요?', 'Vận chuyển là gì?', '["운반이란 작업자가 직접 물건이나 자재를 들기, 밀기, 당기기 등으로 한 장소에서 다른 장소로 이동시키는 행위입니다.", "운반은 물건을 한 장소에서 다른 장소로 옮기는 것입니다."]'::jsonb, '["Vận chuyển là hành động người lao động di chuyển đồ vật hoặc vật liệu từ nơi này sang nơi khác bằng cách trực tiếp mang, đẩy, kéo, v.v.", "Vận chuyển là việc di chuyển đồ vật từ nơi này đến nơi khác."]'::jsonb, 'during_work', 18, '중량물 운반 시 운반기구 활용', 'Khi vận chuyển vật nặng, phải sử dụng dụng cụ hỗ trợ vận chuyển'),
(md5('safety:중량물 운반 시 왜 운반기구를 활용해야 할까요?')::uuid, '중량물 운반 시 왜 운반기구를 활용해야 할까요?', 'Tại sao khi vận chuyển vật nặng cần sử dụng dụng cụ vận chuyển?', '["중량물 운반 시 운반기구를 활용해야 하는 이유는 작업자가 무거운 물건을 몸을 사용하여 운반할 경우 허리 등을 다칠 위험이 크기 때문입니다.", "몸으로 운반하면 다칠 위험이 크기 때문입니다."]'::jsonb, '["Lý do cần sử dụng dụng cụ vận chuyển khi vận chuyển vật nặng là: Nếu người lao động dùng sức của cơ thể để vận chuyển vật nặng thì nguy cơ bị chấn thương, đặc biệt là chấn thương vùng thắt lưng, rất cao.", "Vì nếu dùng sức của cơ thể để vận chuyển thì nguy cơ bị thương rất cao."]'::jsonb, 'during_work', 18, '중량물 운반 시 운반기구 활용', 'Khi vận chuyển vật nặng, phải sử dụng dụng cụ hỗ trợ vận chuyển'),
(md5('safety:안전 통로가 무엇인가요?')::uuid, '안전 통로가 무엇인가요?', 'Lối đi an toàn là gì?', '["안전통로란 작업자가 위험을 피하면서 안전하게 이동할 수 있도록 확보된 통행 공간입니다."]'::jsonb, '["Lối đi an toàn là khu vực được bố trí để người lao động có thể di chuyển an toàn, tránh các nguy hiểm."]'::jsonb, 'during_work', 19, '이동 시 안전통로 이용', 'Khi di chuyển, phải đi theo lối đi an toàn'),
(md5('safety:이동 시 왜 안전통로를 이용해야 할까요?')::uuid, '이동 시 왜 안전통로를 이용해야 할까요?', 'Tại sao khi di chuyển phải sử dụng lối đi an toàn?', '["이동 시 안전통로를 이용해야 하는 이유는 장애물, 기계 등 위험요인이 없는 안전통로를 이용해야 작업자가 안전하게 위치를 옮길 수 있기 때문입니다.", "안전통로는 위험요인이 없어 안전하게 이동할 수 있기 때문입니다."]'::jsonb, '["Lý do khi di chuyển phải sử dụng lối đi an toàn là: vì lối đi an toàn không có các yếu tố nguy hiểm như chướng ngại vật, máy móc, nên người lao động có thể di chuyển một cách an toàn.", "Vì lối đi an toàn không có các yếu tố nguy hiểm nên có thể di chuyển một cách an toàn."]'::jsonb, 'during_work', 19, '이동 시 안전통로 이용', 'Khi di chuyển, phải đi theo lối đi an toàn'),
(md5('safety:이동이 무엇 뜻인가요?')::uuid, '이동이 무엇 뜻인가요?', '“Di chuyển” có nghĩa là gì?', '["이동이란 작업자가 한 장소에서 다른 장소로 위치를 옮기는 행위입니다."]'::jsonb, '["Di chuyển là hành động người lao động thay đổi vị trí từ nơi này sang nơi khác."]'::jsonb, 'during_work', 19, '이동 시 안전통로 이용', 'Khi di chuyển, phải đi theo lối đi an toàn'),
(md5('safety:작업 중 왜 휴대폰을 사용하면 안 될까요?')::uuid, '작업 중 왜 휴대폰을 사용하면 안 될까요?', 'Tại sao không được sử dụng điện thoại khi đang làm việc?', '["작업자의 주의가 분산되어 업무에 집중할 수 없고 사고의 위험이 급격하게 증가하기 때문입니다."]'::jsonb, '["Vì sự chú ý của người lao động bị phân tán, không thể tập trung vào công việc và nguy cơ xảy ra tai nạn tăng lên đột ngột."]'::jsonb, 'during_work', 20, '작업 중 휴대폰 사용 금지', 'Cấm sử dụng điện thoại di động trong khi làm việc'),
(md5('safety:작업 중이란 무슨 뜻인가요?')::uuid, '작업 중이란 무슨 뜻인가요?', '“Đang làm việc” có nghĩa là gì?', '["작업 중이란 작업자가 업무와 관련된 모든 행위를 수행하는 시간이나 상태입니다."]'::jsonb, '["“Đang làm việc” là thời gian hoặc trạng thái mà người lao động thực hiện tất cả các hành vi liên quan đến công việc."]'::jsonb, 'during_work', 20, '작업 중 휴대폰 사용 금지', 'Cấm sử dụng điện thoại di động trong khi làm việc'),
(md5('safety:작업장에서 정리 정돈 및 청소 왜 해야 할까요?')::uuid, '작업장에서 정리 정돈 및 청소 왜 해야 할까요?', 'Tại sao phải sắp xếp, dọn dẹp và vệ sinh tại nơi làm việc?', '["정리 정돈 및 청소를 해야 하는 이유는 필요한 물건을 쉽고 빠르게 찾아 사용할 수 있고, 흩어진 공구나 이물질은 넘어짐, 미끄러짐 등 사고의 원인이 되기 때문입니다.", "사고를 예방하고 필요한 물건을 쉽게 찾을 수 있기 때문입니다."]'::jsonb, '["Lý do phải sắp xếp, dọn dẹp và vệ sinh là: có thể dễ dàng và nhanh chóng tìm thấy những vật dụng cần thiết để sử dụng, đồng thời dụng cụ hoặc tạp chất vương vãi có thể gây ra tai nạn như vấp ngã, trượt ngã.", "Vì có thể phòng ngừa tai nạn và dễ dàng tìm thấy những vật dụng cần thiết."]'::jsonb, 'after_work', 21, '정리정돈 및 청소', 'Sắp xếp, thu dọn và vệ sinh nơi làm việc'),
(md5('safety:정리 정돈이 무슨 뜻인가요?')::uuid, '정리 정돈이 무슨 뜻인가요?', '“Sắp xếp, dọn dẹp” có nghĩa là gì?', '["정리 정돈이란 안전사고 예방과 작업 효율 향상을 위하여 물건을 정해진 위치에 가지런히 놓고 주변 환경을 깨끗하게 유지하는 활동입니다.", "정리 정돈은 물건을 제자리에 두고 주변 환경을 깨끗하게 하는 것입니다."]'::jsonb, '["“Sắp xếp, dọn dẹp” là hoạt động đặt đồ vật ngay ngắn vào đúng vị trí và giữ môi trường xung quanh sạch sẽ, nhằm phòng ngừa tai nạn và nâng cao hiệu quả công việc.", "Sắp xếp, dọn dẹp là việc đặt đồ vật về đúng chỗ và giữ môi trường xung quanh sạch sẽ."]'::jsonb, 'after_work', 21, '정리정돈 및 청소', 'Sắp xếp, thu dọn và vệ sinh nơi làm việc'),
(md5('safety:청소가 무슨 뜻인가요?')::uuid, '청소가 무슨 뜻인가요?', '“Dọn dẹp” có nghĩa là gì?', '["청소란 작업장이나 시설 내의 먼지, 쓰레기, 기름, 이물질 등을 제거하여 깨끗하게 유지하는 활동입니다.", "청소는 이물질을 제거하여 깨끗하게 유지하는 활동입니다"]'::jsonb, '["Dọn dẹp là hoạt động loại bỏ bụi bẩn, rác, dầu mỡ, tạp chất... trong nơi làm việc hoặc cơ sở, nhằm giữ cho môi trường luôn sạch sẽ.", "Dọn dẹp là hoạt động loại bỏ các tạp chất và giữ cho môi trường sạch sẽ."]'::jsonb, 'after_work', 21, '정리정돈 및 청소', 'Sắp xếp, thu dọn và vệ sinh nơi làm việc'),
(md5('safety:공구가 무엇인가요?')::uuid, '공구가 무엇인가요?', 'Dụng cụ là gì?', '["공구란 작업을 도와주며 보다 쉽고 정확하게 일을 수행하기 위해 사용하는 도구나 기구입니다."]'::jsonb, '["Dụng cụ là những công cụ hoặc thiết bị được sử dụng để hỗ trợ công việc, giúp thực hiện công việc dễ dàng và chính xác hơn."]'::jsonb, 'after_work', 22, '공구는 지정된 자리에 두기', 'Đặt dụng cụ đúng vị trí quy định'),
(md5('safety:공구를 왜 지정된 자리에 두어야 할까요?')::uuid, '공구를 왜 지정된 자리에 두어야 할까요?', 'Tại sao phải để dụng cụ vào đúng vị trí được chỉ định?', '["공구를 지정된 자리에 두어야 하는 이유는 공구가 분실되거나 파손될 위험이 있으며 바닥, 통로, 기계 위에 있으면 사고 발생 위험이 크기 때문입니다.", "공구가 분실되거나 아무렇게나 두면 사고가 발생할 수 있기 때문입니다."]'::jsonb, '["Lý do phải để dụng cụ vào đúng vị trí được chỉ định là: dụng cụ có thể bị mất hoặc hư hỏng, và nếu để trên sàn, lối đi hoặc máy móc thì nguy cơ xảy ra tai nạn rất cao.", "Vì dụng cụ có thể bị mất hoặc nếu đặt bừa bãi có thể xảy ra tai nạn."]'::jsonb, 'after_work', 22, '공구는 지정된 자리에 두기', 'Đặt dụng cụ đúng vị trí quy định'),
(md5('safety:지정된 자리는 무슨 뜻인가요?')::uuid, '지정된 자리는 무슨 뜻인가요?', '“Vị trí được chỉ định” có nghĩa là gì?', '["지정된 자리란 사고 예방과 작업 효율성 확보를 위해 사전에 정해진 위치나 장소로 특정 물건이나 사람이 있어야 할 곳입니다.", "사전에 정해진 위치나 장소로 특정 물건이나 사람이 있어야 할 곳입니다."]'::jsonb, '["Vị trí được chỉ định là vị trí hoặc nơi đã được quy định trước, nơi một vật hoặc một người cần phải ở đó, nhằm phòng ngừa tai nạn và đảm bảo hiệu quả công việc.", "Là vị trí hoặc nơi đã được quy định trước, nơi một vật hoặc một người cụ thể cần phải ở đó."]'::jsonb, 'after_work', 22, '공구는 지정된 자리에 두기', 'Đặt dụng cụ đúng vị trí quy định'),
(md5('safety:손 씻기 등 위생관리를 왜 해야 할까요?')::uuid, '손 씻기 등 위생관리를 왜 해야 할까요?', 'Tại sao phải thực hiện quản lý vệ sinh như rửa tay?', '["위생관리를 해야 하는 이유는 작업장에서 발생하는 이물질이나 화학물질이 손, 입, 눈, 피부를 통해 몸속으로 들어가 질병을 유발할 수 있기 때문입니다.", "유해물질이 몸에 들어가 질병을 유발할 수 있기 때문입니다."]'::jsonb, '["Lý do phải thực hiện quản lý vệ sinh là: vì các tạp chất hoặc hóa chất phát sinh tại nơi làm việc có thể xâm nhập vào cơ thể qua tay, miệng, mắt hoặc da và gây ra bệnh tật.", "Vì các chất có hại có thể xâm nhập vào cơ thể và gây ra bệnh tật."]'::jsonb, 'after_work', 23, '손 씻기 등 위생관리 철저', 'Thực hiện nghiêm túc vệ sinh cá nhân, như rửa tay'),
(md5('safety:위생관리가 무슨 뜻인가요?')::uuid, '위생관리가 무슨 뜻인가요?', '“Quản lý vệ sinh” có nghĩa là gì?', '["위생관리란 작업자와 작업환경의 청결을 유지하고 유해요인으로부터 건강을 보호하기 위한 모든 관리 활동입니다.", "유해요인으로부터 건강을 보호하기 위해 청결을 유지하는 활동입니다."]'::jsonb, '["“Quản lý vệ sinh” là tất cả các hoạt động quản lý nhằm duy trì sự sạch sẽ của người lao động và môi trường làm việc, đồng thời bảo vệ sức khỏe khỏi các yếu tố có hại.", "Là hoạt động duy trì sự sạch sẽ để bảo vệ sức khỏe khỏi các yếu tố có hại."]'::jsonb, 'after_work', 23, '손 씻기 등 위생관리 철저', 'Thực hiện nghiêm túc vệ sinh cá nhân, như rửa tay'),
(md5('safety:작업 후 밥 먹기 전에 무엇을 해야 하나요?')::uuid, '작업 후 밥 먹기 전에 무엇을 해야 하나요?', 'Sau khi làm việc, trước khi ăn cơm cần phải làm gì?', '["밥 먹기 전에는 손을 깨끗이 씻어야 합니다."]'::jsonb, '["Trước khi ăn cơm, phải rửa tay thật sạch"]'::jsonb, 'after_work', 23, '손 씻기 등 위생관리 철저', 'Thực hiện nghiêm túc vệ sinh cá nhân, như rửa tay'),
(md5('safety:기계의 청소·수리 작업 전에는 무엇을 해야 하나요?')::uuid, '기계의 청소·수리 작업 전에는 무엇을 해야 하나요?', 'Trước khi thực hiện công việc vệ sinh, sửa chữa máy móc thì phải làm gì?', '["기계의 청소·수리 전에는 전원을 차단해야 합니다."]'::jsonb, '["Trước khi vệ sinh, sửa chữa máy móc, phải ngắt nguồn điện."]'::jsonb, 'after_work', 24, '청소·수리 작업 시 기계 전원 차단', 'Khi vệ sinh hoặc sửa chữa máy, phải ngắt nguồn điện của máy'),
(md5('safety:전원 차단이 무슨 뜻인가요?')::uuid, '전원 차단이 무슨 뜻인가요?', '“Ngắt nguồn điện” có nghĩa là gì?', '["전원 차단이란 기계, 설비의 갑작스러운 작동을 방지하기 위하여 공급되는 전기 등을 완전히 끊는 조치입니다.", "기계, 설비를 멈추기 위해 전기를 끊는 조치입니다."]'::jsonb, '["Ngắt nguồn điện là biện pháp ngắt hoàn toàn nguồn điện hoặc các nguồn cung cấp năng lượng khác cho máy móc, thiết bị nhằm ngăn máy móc, thiết bị đột ngột hoạt động.", "Là biện pháp ngắt điện để dừng máy móc, thiết bị."]'::jsonb, 'after_work', 24, '청소·수리 작업 시 기계 전원 차단', 'Khi vệ sinh hoặc sửa chữa máy, phải ngắt nguồn điện của máy'),
(md5('safety:청소·수리 작업 시 왜 기계 전원을 차단 해야 할까요?')::uuid, '청소·수리 작업 시 왜 기계 전원을 차단 해야 할까요?', 'Tại sao khi thực hiện công việc vệ sinh, sửa chữa phải ngắt nguồn điện của máy móc?', '["청소·수리 작업 시 기계 전원을 차단해야 하는 이유는 청소·수리 작업은 작업자가 기계 내부나 위험한 부위에 직접 접근해야 하는 고위험 작업이기 때문입니다.", "기계 내부나 위험한 부위에 접근하는 고위험 작업이기 때문입니다."]'::jsonb, '["Lý do phải ngắt nguồn điện của máy khi thực hiện công việc vệ sinh, sửa chữa là: Vì đây là công việc có nguy cơ cao, trong đó người lao động phải trực tiếp tiếp cận bên trong máy hoặc các bộ phận nguy hiểm.", "Vì đây là công việc có nguy cơ cao phải tiếp cận bên trong máy hoặc các bộ phận nguy hiểm."]'::jsonb, 'after_work', 24, '청소·수리 작업 시 기계 전원 차단', 'Khi vệ sinh hoặc sửa chữa máy, phải ngắt nguồn điện của máy'),
(md5('safety:청소·수리 작업이 무엇인가요?')::uuid, '청소·수리 작업이 무엇인가요?', 'Công việc sửa chữa và vệ sinh là gì?', '["청소·수리 작업이란 기계나 설비의 이물질을 제거하거나 고장 난 부분을 교체하거나 복구하기 위해 실시하는 작업입니다."]'::jsonb, '["Công việc vệ sinh và sửa chữa là công việc được thực hiện để loại bỏ tạp chất khỏi máy móc, thiết bị hoặc thay thế, khôi phục những bộ phận bị hỏng."]'::jsonb, 'after_work', 24, '청소·수리 작업 시 기계 전원 차단', 'Khi vệ sinh hoặc sửa chữa máy, phải ngắt nguồn điện của máy'),
(md5('safety:불씨·불티가 무엇인가요?')::uuid, '불씨·불티가 무엇인가요?', 'Đốm lửa - tàn lửa là gì?', '["불씨·불티란 완전히 꺼지지 않은 작은 불덩이 또는 불꽃으로 눈에는 잘 안 보이지만 오랜 시간 열을 유지하는 작고 뜨거운 열원입니다.", "불씨·불티는 완전히 꺼지지 않은 작은 불꽃입니다."]'::jsonb, '["Đốm lửa - tàn lửa là những đốm lửa nhỏ chưa tắt hoàn toàn hoặc những nguồn nhiệt nhỏ, nóng, khó nhìn thấy bằng mắt thường nhưng có thể duy trì nhiệt trong thời gian dài.", "Câu này bỏ"]'::jsonb, 'after_work', 25, '화기 취급 시 불씨·불티 확인', 'Khi sử dụng nguồn lửa, phải kiểm tra tia lửa và tàn lửa'),
(md5('safety:소화기를 사용할 줄 아나요? 소화기 사용 시 제일 먼저 해야 하는 것은?')::uuid, '소화기를 사용할 줄 아나요? 소화기 사용 시 제일 먼저 해야 하는 것은?', 'Bạn có biết cách sử dụng bình chữa cháy không? Khi sử dụng bình chữa cháy, việc đầu tiên cần làm là gì?', '["소화기를 사용할 때는 안전핀을 먼저 뽑아야 합니다. 화기 작업 할 때는 소화기를 근처에 두어야 합니다.", "네,안전핀을 먼저 뽑아야 합니다."]'::jsonb, '["Khi sử dụng bình chữa cháy, trước tiên phải rút chốt an toàn. Khi thực hiện công việc có nguồn lửa, cần đặt bình chữa cháy ở gần.", "Có. Trước tiên phải rút chốt an toàn."]'::jsonb, 'after_work', 25, '화기 취급 시 불씨·불티 확인', 'Khi sử dụng nguồn lửa, phải kiểm tra tia lửa và tàn lửa'),
(md5('safety:화기 취급 시 왜 불씨·불티를 확인해야 할까요?')::uuid, '화기 취급 시 왜 불씨·불티를 확인해야 할까요?', 'Tại sao khi sử dụng và xử lý nguồn lửa cần phải kiểm tra tàn lửa, đốm lửa?', '["화기 취급 작업 종료 후 불씨·불티를 확인하여야 하는 이유는 불씨·불티가 남아 있을 경우, 시간이 지나고 나서 예상하지 못한 장소에서 화재가 발생할 수 있기 때문입니다.", "불씨·불티가 남아 화재가 발생할 수 있기 때문입니다."]'::jsonb, '["—> Lý do phải kiểm tra tàn lửa, tia lửa sau khi kết thúc công việc sử dụng nguồn lửa là nếu còn sót lại tàn lửa, tia lửa thì sau một thời gian, hỏa hoạn có thể xảy ra ở những nơi không ngờ tới.", "Vì tàn lửa, tia lửa còn sót lại có thể gây ra hỏa hoạn."]'::jsonb, 'after_work', 25, '화기 취급 시 불씨·불티 확인', 'Khi sử dụng nguồn lửa, phải kiểm tra tia lửa và tàn lửa'),
(md5('safety:화기 취급이 무엇인가요?')::uuid, '화기 취급이 무엇인가요?', 'Việc sử dụng và xử lý nguồn lửa là gì?', '["화기란 작업 현장에서 불꽃, 불티, 열을 발생시킬 수 있는 모든 기구와 장치입니다.", "화기 취급이란 불꽃, 불티, 열을 발생시킬 수 있는 기구와 장치를 사용하는 것입니다."]'::jsonb, '["Nguồn lửa các dụng cụ và thiết bị có thể tạo ra tia lửa, đốm lửa hoặc nhiệt tại nơi làm việc.", "Việc sử dụng và xử lý nguồn lửa là việc sử dụng các dụng cụ và thiết bị có thể phát sinh ngọn lửa, tia lửa hoặc nhiệt."]'::jsonb, 'after_work', 25, '화기 취급 시 불씨·불티 확인', 'Khi sử dụng nguồn lửa, phải kiểm tra tia lửa và tàn lửa'),
(md5('safety:119 전화번호를 알고 있나요?')::uuid, '119 전화번호를 알고 있나요?', 'Bạn có biết số điện thoại 119 không?', '["119 번호는 대한민국에서 불이 났을 때나 응급환자가 생겼을 때 소방서로 연결되는 전화번호입니다.", "119는 화재나 응급상황 때 신고하는 번호입니다."]'::jsonb, '["Số điện thoại 119 là số điện thoại kết nối với cơ quan cứu hỏa ở Hàn Quốc khi xảy ra hỏa hoạn hoặc có người cần cấp cứu.", "119 là số điện thoại để báo cháy hoặc báo các tình huống khẩn cấp."]'::jsonb, 'incident_response', 26, '화재 시 대피 우선', 'Khi xảy ra hỏa hoạn, ưu tiên sơ tán'),
(md5('safety:대피가 무엇인가요?')::uuid, '대피가 무엇인가요?', 'Sơ tán là gì?', '["대피란 화재 등 위험한 상황이 발생했을 때, 작업자의 생명과 신체를 보호하기 위해 안전한 장소로 신속히 이동하는 행위입니다.", "대피는 위험할 때 안전한 곳으로 이동하는 것입니다."]'::jsonb, '["Sơ tán là hành động nhanh chóng di chuyển đến nơi an toàn để bảo vệ tính mạng và cơ thể của người lao động khi xảy ra tình huống nguy hiểm như hỏa hoạn.", "Sơ tán là di chuyển đến nơi an toàn khi gặp nguy hiểm."]'::jsonb, 'incident_response', 26, '화재 시 대피 우선', 'Khi xảy ra hỏa hoạn, ưu tiên sơ tán'),
(md5('safety:화재 시 왜 대피가 우선일까요?')::uuid, '화재 시 왜 대피가 우선일까요?', 'Tại sao khi xảy ra hỏa hoạn, việc sơ tán lại được ưu tiên?', '["화재 시 대피가 우선인 이유는 화재가 발생하면 불길보다 연기, 유독가스 등이 생명을 위협하고 재산보다는 사람의 생명이 우선이기 때문입니다.", "연기와 유독가스가 생명을 위협하고 생명이 가장 중요하기 때문입니다.", "연기와 유독가스가 생명을 위협하기 때문입니다."]'::jsonb, '["Lý do khi xảy ra hỏa hoạn, việc sơ tán được ưu tiên là vì khi xảy ra cháy, khói và khí độc đe dọa tính mạng, đồng thời tính mạng con người được ưu tiên hơn tài sản.", "Vì khói và khí độc đe dọa tính mạng, và tính mạng là quan trọng nhất.", "Vì khói và khí độc đe dọa tính mạng."]'::jsonb, 'incident_response', 26, '화재 시 대피 우선', 'Khi xảy ra hỏa hoạn, ưu tiên sơ tán'),
(md5('safety:화재가 무엇인가요?')::uuid, '화재가 무엇인가요?', 'Hỏa hoạn là gì?', '["화재란 탈 수 있는 물질이 공기 중의 산소와 불꽃 등을 만나 열과 빛을 내며 타는 것입니다."]'::jsonb, '["Hỏa hoạn là hiện tượng vật liệu có thể cháy gặp oxy trong không khí và ngọn lửa, tạo ra nhiệt và ánh sáng rồi cháy."]'::jsonb, 'incident_response', 26, '화재 시 대피 우선', 'Khi xảy ra hỏa hoạn, ưu tiên sơ tán'),
(md5('safety:모르는 작업 무슨 뜻인가요?')::uuid, '모르는 작업 무슨 뜻인가요?', 'Công việc không biết / công việc chưa biết cách làm là gì?', '["모르는 작업이란 작업자가 작업 내용이나 방법을 정확히 알지 못하거나 충분한 교육 없이 수행하게 되는 작업입니다.", "모르는 작업은 교육을 받지 않았거나 작업 방법을 모르는 작업입니다."]'::jsonb, '["Là công việc mà người lao động không biết rõ nội dung hoặc phương pháp thực hiện, hoặc phải thực hiện khi chưa được đào tạo đầy đủ.", "Là công việc không được đào tạo hoặc không biết cách thực hiện công việc."]'::jsonb, 'incident_response', 27, '모르는 작업은 물어보기', 'Nếu không biết cách thực hiện công việc, hãy hỏi'),
(md5('safety:모르는 작업은 왜 물어봐야 할까요?')::uuid, '모르는 작업은 왜 물어봐야 할까요?', 'Tại sao khi không biết cách làm công việc thì phải hỏi?', '["모르는 작업을 물어봐야 하는 이유는 작업 내용을 정확히 모른거나 확신이 없는 상태에서 작업하는 것은 자신과 동료의 생명과 안전까지 위험할 수 있기 때문입니다.", "작업을 잘 모르고 하면 자신과 동료의 생명과 안전까지 위험할 수 있기 때문입니다.", "작업을 잘 모르고 하면 사고가 발생할 수 있기 때문입니다."]'::jsonb, '["Lý do phải hỏi khi không biết công việc là nếu làm việc trong tình trạng không hiểu rõ nội dung công việc hoặc không chắc chắn, có thể gây nguy hiểm đến tính mạng và sự an toàn của bản thân và đồng nghiệp.", "Vì nếu làm việc mà không hiểu rõ, có thể gây nguy hiểm đến tính mạng và sự an toàn của bản thân và đồng nghiệp.", "Vì nếu làm việc mà không hiểu rõ có thể xảy ra tai nạn."]'::jsonb, 'incident_response', 27, '모르는 작업은 물어보기', 'Nếu không biết cách thực hiện công việc, hãy hỏi'),
(md5('safety:물어보기가 무슨 뜻인가요?')::uuid, '물어보기가 무슨 뜻인가요?', 'Hỏi có nghĩa là gì?', '["물어보기란 모르는 것이나 불확실한 사항에 대하여 정확한 정보를 얻기 위하여 다른 사람에게 질문하는 행위입니다.", "무엇을 알아내기 위하여 다른 사람에게 질문하는 행위입니다."]'::jsonb, '["Hỏi là hành động đặt câu hỏi cho người khác để có được thông tin chính xác về những điều mình không biết hoặc chưa chắc chắn.", "Là hành động hỏi người khác để tìm hiểu một điều gì đó."]'::jsonb, 'incident_response', 27, '모르는 작업은 물어보기', 'Nếu không biết cách thực hiện công việc, hãy hỏi'),
(md5('safety:발견이 무슨 뜻인가요?')::uuid, '발견이 무슨 뜻인가요?', 'Phát hiện / tìm thấy có nghĩa là gì?', '["발견이란 숨겨져 있거나 보이지 않던 위험요인, 고장, 불량, 이상 상태 등을 알아차리거나 찾아내는 것입니다.", "발견은 위험이나 이상을 찾아내는 것입니다."]'::jsonb, '["Phát hiện là việc nhận ra hoặc tìm ra những yếu tố nguy hiểm, hư hỏng, lỗi, tình trạng bất thường... vốn bị che khuất hoặc không nhìn thấy.", "hát hiện là tìm ra những nguy hiểm hoặc điều bất thường."]'::jsonb, 'incident_response', 28, '사고위험 발견 시 알려주기', 'Khi phát hiện nguy cơ tai nạn, phải báo ngay'),
(md5('safety:사고 위험이 무엇인가요?')::uuid, '사고 위험이 무엇인가요?', 'Nguy cơ tai nạn là gì?', '["사고 위험이란 작업 중 예상하지 못한 일로 작업자가 다치거나 재산상의 피해를 입을 수 있는 위험요인입니다.", "사고 위험은 작업 중 다치거나 사고가 발생할 수 있는 위험입니다."]'::jsonb, '["Nguy cơ tai nạn là những yếu tố nguy hiểm có thể khiến người lao động bị thương hoặc gây thiệt hại về tài sản do những sự việc không lường trước được trong quá trình làm việc.", "Nguy cơ tai nạn là nguy cơ bị thương hoặc xảy ra tai nạn trong quá trình làm việc."]'::jsonb, 'incident_response', 28, '사고위험 발견 시 알려주기', 'Khi phát hiện nguy cơ tai nạn, phải báo ngay'),
(md5('safety:사고위험 발견 시 왜 알려줘야 할까요?')::uuid, '사고위험 발견 시 왜 알려줘야 할까요?', 'Tại sao khi phát hiện nguy cơ tai nạn thì phải báo cho người khác?', '["사고위험 발견 시 알려줘야 하는 이유는 사고위험을 발견하고도 알리지 않으면, 그 위험은 그대로 방치되어 작업자와 동료의 생명과 안전을 위협하기 때문입니다.", "사고위험을 발견하고도 알리지 않으면 작업자와 동료의 생명과 안전을 위협하기 때문입니다."]'::jsonb, '["Lý do khi phát hiện nguy cơ tai nạn phải báo cho người khác là nếu phát hiện nguy cơ tai nạn nhưng không báo, nguy cơ đó sẽ tiếp tục bị bỏ mặc và đe dọa đến tính mạng, sự an toàn của bản thân và đồng nghiệp.", "Vì nếu phát hiện nguy cơ tai nạn nhưng không báo, nó sẽ đe dọa đến tính mạng và sự an toàn của bản thân và đồng nghiệp."]'::jsonb, 'incident_response', 28, '사고위험 발견 시 알려주기', 'Khi phát hiện nguy cơ tai nạn, phải báo ngay'),
(md5('safety:날씨가 너무 더우면 어떻게 해야 하나요?')::uuid, '날씨가 너무 더우면 어떻게 해야 하나요?', 'Khi thời tiết quá nóng thì phải làm gì?', '["물을 자주 마시고 그늘에서 자주 휴식을 취합니다."]'::jsonb, '["Uống nước thường xuyên và thường xuyên nghỉ ngơi ở nơi có bóng râm."]'::jsonb, 'incident_response', 29, '폭염 시 물, 그늘, 휴식', 'Khi nắng nóng: Uống nước – Nghỉ nơi có bóng mát – Nghỉ ngơi'),
(md5('safety:폭염 시 왜 물, 그늘, 휴식을 해야 할까요?')::uuid, '폭염 시 왜 물, 그늘, 휴식을 해야 할까요?', 'Khi trời nắng nóng gay gắt, tại sao cần uống nước, ở nơi có bóng râm và nghỉ ngơi?', '["폭염 시 물, 그늘, 휴식을 해야 하는 이유는 폭염 상태에서의 작업은 작업자의 체온 상승과 몸 속 수분 손실을 빠르게 하여 생명까지 위험받을 수 있기 때문입니다.", "체온이 올라가고 몸에 수분이 부족해 생명이 위험할 수 있기 때문입니다."]'::jsonb, '["Lý do khi trời nắng nóng gay gắt cần uống nước, ở nơi có bóng râm và nghỉ ngơi là vì làm việc trong điều kiện nắng nóng gay gắt khiến nhiệt độ cơ thể tăng và cơ thể mất nước nhanh chóng, có thể gây nguy hiểm đến tính mạng.", "Vì nhiệt độ cơ thể tăng và cơ thể bị thiếu nước, có thể gây nguy hiểm đến tính mạng."]'::jsonb, 'incident_response', 29, '폭염 시 물, 그늘, 휴식', 'Khi nắng nóng: Uống nước – Nghỉ nơi có bóng mát – Nghỉ ngơi'),
(md5('safety:폭염이 무엇인가요?')::uuid, '폭염이 무엇인가요?', 'Nắng nóng gay gắt là gì?', '["폭염이란 기온이 매우 높고 무더운 상태가 일정 기간 지속되는 현상으로 최고기온이 33도(℃) 이상인 날이 2일 이상 계속되는 경우입니다.", "폭염은 33도 이상의 더운 날씨가 2일 이상 계속되는 현상입니다."]'::jsonb, '["Nắng nóng gay gắt là hiện tượng nhiệt độ rất cao, thời tiết nóng bức kéo dài trong một khoảng thời gian nhất định, với nhiệt độ cao nhất từ 33°C trở lên trong 2 ngày liên tiếp.", "Nắng nóng gay gắt là hiện tượng thời tiết nóng từ 33°C trở lên kéo dài từ 2 ngày trở lên."]'::jsonb, 'incident_response', 29, '폭염 시 물, 그늘, 휴식', 'Khi nắng nóng: Uống nước – Nghỉ nơi có bóng mát – Nghỉ ngơi'),
(md5('safety:대피가 무슨 뜻인가요?')::uuid, '대피가 무슨 뜻인가요?', 'Sơ tán có nghĩa là gì?', '["대피란 위험한 상황이 발생했을 때, 작업자의 생명과 신체를 보호하기 위해 안전한 장소로 신속히 이동하는 행위입니다.", "대피는 위험할 때 안전한 곳으로 이동하는 것입니다."]'::jsonb, '["Sơ tán là hành động nhanh chóng di chuyển đến nơi an toàn để bảo vệ tính mạng và cơ thể của người lao động khi xảy ra tình huống nguy hiểm.", "Sơ tán là di chuyển đến nơi an toàn khi gặp nguy hiểm."]'::jsonb, 'incident_response', 30, '사고 위험 시 작업 중지 및 대피', 'Khi có nguy cơ xảy ra tai nạn, phải dừng công việc và sơ tán'),
(md5('safety:사고 위험 시 왜 작업을 중지하고 대피해야 할까요?')::uuid, '사고 위험 시 왜 작업을 중지하고 대피해야 할까요?', 'Tại sao khi có nguy cơ xảy ra tai nạn, phải dừng công việc và sơ tán?', '["사고 위험 시 작업을 중지하고 대피해야 하는 이유는 작업을 멈추고 위험 상황에서 즉시 벗어나는 것은 기계, 설비보다 사람의 생명이 더 소중하기 때문입니다.", "사람의 생명이 가장 중요하기 때문입니다."]'::jsonb, '["Lý do khi có nguy cơ xảy ra tai nạn phải dừng công việc và sơ tán là vì việc dừng công việc và lập tức rời khỏi khu vực nguy hiểm là cần thiết, bởi tính mạng con người quan trọng hơn máy móc và thiết bị.", "Vì tính mạng con người là quan trọng nhất."]'::jsonb, 'incident_response', 30, '사고 위험 시 작업 중지 및 대피', 'Khi có nguy cơ xảy ra tai nạn, phải dừng công việc và sơ tán'),
(md5('safety:사고의 위험이 있으면 어떻게 해야 하나요?')::uuid, '사고의 위험이 있으면 어떻게 해야 하나요?', 'Nếu có nguy cơ xảy ra tai nạn thì phải làm gì?', '["사고 위험이 있으면 우선 작업을 중지하고 안전한 곳으로 대피해야 합니다."]'::jsonb, '["Nếu có nguy cơ xảy ra tai nạn, trước tiên phải dừng công việc và sơ tán đến nơi an toàn."]'::jsonb, 'incident_response', 30, '사고 위험 시 작업 중지 및 대피', 'Khi có nguy cơ xảy ra tai nạn, phải dừng công việc và sơ tán'),
(md5('safety:작업 중지가 무엇인가요?')::uuid, '작업 중지가 무엇인가요?', 'Dừng công việc là gì?', '["작업 중지란 작업 도중 안전상 위험이 있다고 판단되거나 실제 사고가 발생할 우려가 있을 때, 즉시 작업을 멈추는 것입니다", "작업 중지는 위험이 있다고 판단되거나 사고가 발생할 우려가 있을 때 즉시 작업을 멈추는 것입니다."]'::jsonb, '["Dừng công việc là việc lập tức ngừng công việc khi nhận thấy có nguy hiểm về mặt an toàn hoặc có nguy cơ xảy ra tai nạn trong quá trình làm việc.", "Dừng công việc là lập tức ngừng công việc khi nhận thấy có nguy hiểm hoặc có nguy cơ xảy ra tai nạn."]'::jsonb, 'incident_response', 30, '사고 위험 시 작업 중지 및 대피', 'Khi có nguy cơ xảy ra tai nạn, phải dừng công việc và sơ tán');
INSERT INTO public.interview_questions (
